INSERT INTO sections (slug, name_ja, sort_order) VALUES ('reading', 'Reading', 2) ON CONFLICT(slug) DO NOTHING;
INSERT INTO sections (slug, name_ja, sort_order) VALUES ('listening', 'Listening', 3) ON CONFLICT(slug) DO NOTHING;
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-horse', 'reading', 'The Domestication of the Horse', 'Archaeologists have long debated when and where humans first domesticated the horse. For much of the twentieth century, the prevailing view held that horse domestication began on the Eurasian steppe, in what is now Kazakhstan, roughly six thousand years ago. This theory rested largely on indirect evidence: wear patterns on horse teeth suggested the use of bits, and unusually large deposits of horse bones at certain sites hinted at organized herding rather than opportunistic hunting.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-coral', 'reading', 'Coral Bleaching', 'Coral reefs, though they occupy less than one percent of the ocean floor, support roughly a quarter of all known marine species. This extraordinary productivity depends on a partnership between coral polyps, tiny animals related to sea anemones, and microscopic algae called zooxanthellae that live within the polyps'' tissues. The algae photosynthesize and supply the coral with nutrients, while the coral provides the algae with a protected habitat and compounds needed for photosynthesis. It is the pigments within these algae that give healthy reefs their vivid colors.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-insulin', 'reading', 'The Discovery of Insulin', 'Before the 1920s, a diagnosis of type 1 diabetes was effectively a death sentence, particularly for children, who often survived only a few years after symptoms appeared. The disease''s connection to the pancreas had been suspected since the 1880s, after researchers observed that dogs whose pancreases were surgically removed developed symptoms strikingly similar to diabetes. Yet decades of attempts to isolate the pancreatic substance responsible for regulating blood sugar had failed, largely because digestive enzymes in the pancreas broke down the substance before it could be extracted in usable form.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-urban-heat', 'reading', 'Urban Heat Islands', 'Cities are, on average, measurably warmer than the rural areas that surround them, a phenomenon known as the urban heat island effect. Temperature differences between a city center and its outskirts can exceed five degrees Celsius on a calm, clear evening, though the effect is generally smaller during the day and in windy or cloudy conditions. The primary cause is not a mystery: materials common in urban construction, such as asphalt and dark rooftops, absorb far more solar radiation during the day than natural vegetation does, then slowly release that stored heat after sunset.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-silk-road', 'reading', 'The Silk Road''s Economic Legacy', 'The term "Silk Road" evokes images of camel caravans carrying silk from China to the Mediterranean, but the network of overland and maritime routes it describes carried far more than a single luxury good, and served a much wider economic function than simple long-distance trade. Spices, precious stones, glassware, paper-making technology, and even certain crops traveled these routes in both directions over roughly fifteen centuries, from around 130 BCE until the network''s decline in the fifteenth century following the rise of direct sea trade between Europe and Asia.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-impressionism', 'reading', 'The Rise of Impressionist Painting', 'In 1874, a group of Paris-based artists, denied entry into the officially sanctioned Salon exhibition, organized an independent show of their own work. Critics were largely unkind: one, mocking a Claude Monet painting titled "Impression, Sunrise", coined the term "Impressionist" as an insult, suggesting the works looked unfinished, as if the artists had captured only a fleeting impression rather than a fully realized scene. The label, intended to dismiss the movement, was instead adopted by the artists themselves.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-photosynthesis', 'reading', 'C4 Photosynthesis and Heat Tolerance', 'Most plants rely on a photosynthetic pathway known as C3 photosynthesis, in which the enzyme RuBisCO fixes carbon dioxide directly into a three-carbon compound. This pathway works efficiently under moderate temperatures, but in hot, dry conditions, RuBisCO increasingly binds oxygen instead of carbon dioxide, a wasteful side reaction called photorespiration that reduces the energy available for growth.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-bronze-age', 'reading', 'The Bronze Age Collapse', 'Around 1200 BCE, a number of powerful civilizations across the eastern Mediterranean and Near East, including the Hittite Empire, Mycenaean Greece, and numerous city-states along the Levantine coast, experienced a rapid and largely simultaneous decline within the span of a few decades. Major palace complexes were destroyed or abandoned, long-distance trade networks that had connected these societies collapsed, and writing systems used for administrative record-keeping disappeared in several regions for centuries afterward.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-loss-aversion', 'reading', 'Loss Aversion in Behavioral Economics', 'Classical economic theory long assumed that people evaluate financial decisions rationally, weighing potential gains and losses of equal size as equivalent in importance. Research in behavioral economics, however, has repeatedly shown that this assumption does not match how people actually behave. In a series of experiments beginning in the late 1970s, psychologists Daniel Kahneman and Amos Tversky demonstrated that people tend to feel the pain of a loss roughly twice as intensely as the pleasure of an equivalent gain, a pattern they termed loss aversion.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-plate-tectonics', 'reading', 'From Continental Drift to Plate Tectonics', 'In 1912, the German meteorologist Alfred Wegener proposed that the continents had once been joined together in a single landmass, which he called Pangaea, before gradually drifting apart to their current positions. As evidence, he pointed to the way the coastlines of South America and Africa appeared to fit together like puzzle pieces, as well as matching rock formations and fossils of the same land-dwelling species found on continents now separated by vast oceans.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-printing-press', 'reading', 'The Printing Press and the Spread of Knowledge', 'Around 1450, the German goldsmith Johannes Gutenberg introduced a printing system in Europe that combined movable metal type, an oil-based ink suited to metal surfaces, and a modified wine press to apply even pressure to paper. While woodblock printing and even earlier forms of movable type had existed in East Asia for centuries, Gutenberg''s particular combination of technologies proved remarkably well suited to the alphabetic scripts used in Europe, since a relatively small set of reusable letter molds could be rearranged to print any text.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-octopus', 'reading', 'Octopus Cognition and Camouflage', 'Octopuses possess a nervous system strikingly different from that of most intelligent animals studied by scientists. Rather than concentrating most neurons in a central brain, roughly two-thirds of an octopus''s several hundred million neurons are distributed throughout its eight arms, allowing each arm to process sensory information and coordinate movement with a surprising degree of independence from the central brain. This distributed architecture has led some researchers to describe octopus cognition as fundamentally different from the centralized intelligence found in vertebrates.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-dust-bowl', 'reading', 'The Dust Bowl of the 1930s', 'During the 1930s, a series of severe dust storms struck the southern Great Plains region of the United States, an area encompassing parts of Texas, Oklahoma, Kansas, Colorado, and New Mexico that came to be known as the Dust Bowl. The storms stripped away millions of tons of topsoil, occasionally carrying dust as far as cities on the East Coast and darkening skies hundreds of miles from their point of origin.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-renaissance-patronage', 'reading', 'The Renaissance Patronage System', 'During the Italian Renaissance, artists rarely worked as independent creators producing pieces for open sale, as is common today. Instead, most operated within a patronage system, in which wealthy individuals, religious institutions, or civic governments commissioned specific works and paid for materials, labor, and often the artist''s living expenses over the course of a project. A patron''s commission typically specified not only the general subject matter but sometimes exact dimensions, materials such as expensive pigments like ultramarine, and even the number of figures to be included.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-bird-navigation', 'reading', 'How Migratory Birds Navigate', 'Every year, many species of birds travel thousands of kilometers between breeding and wintering grounds, often returning to the same nesting site with remarkable precision despite having no apparent way to consult a map. For decades, researchers have investigated how migratory birds manage to navigate over such vast distances, and the current consensus is that birds rely not on a single method but on multiple, overlapping navigational systems.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-assembly-line', 'reading', 'The Invention of the Assembly Line', 'In 1913, Henry Ford''s automobile company introduced a moving assembly line at its Highland Park, Michigan plant, fundamentally changing how manufactured goods were produced. Before this innovation, workers building a Ford automobile moved from station to station, carrying components and assembling entire vehicles largely by hand, a process that could take more than twelve hours per car. Ford''s engineers instead arranged production so that a partially built car moved past stationary workers on a conveyor system, each of whom repeated a single specialized task as the vehicle passed.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-permafrost', 'reading', 'Permafrost Thaw and Methane Release', 'Permafrost is soil, rock, or sediment that has remained frozen for at least two consecutive years, and in many parts of the Arctic it has stayed frozen for thousands of years. It underlies roughly a quarter of the exposed land in the Northern Hemisphere, spanning large areas of Siberia, Alaska, and northern Canada. Trapped within this frozen ground is an enormous reserve of ancient plant and animal material that never fully decomposed because cold temperatures prevented the microorganisms responsible for decay from functioning.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-hammurabi', 'reading', 'The Code of Hammurabi', 'Around 1754 BCE, Hammurabi, the sixth king of the Babylonian dynasty, had a set of laws carved onto a nearly eight-foot stone pillar, or stele, and displayed publicly in the city of Babylon. Though earlier Mesopotamian rulers had issued legal proclamations, Hammurabi''s code stands out for its scope and its ambition to present a unified, systematic body of law covering matters from commerce and property to family disputes and criminal punishment.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-lichen', 'reading', 'Symbiosis in Lichen', 'A lichen is not a single organism but a stable partnership between at least two very different kinds of life: a fungus and a photosynthetic partner, usually a species of algae or, in some cases, a cyanobacterium. Roughly twenty thousand species of lichen have been described, and they grow in an extraordinarily wide range of environments, from tropical rainforests to bare Arctic rock, tree bark, and even the surfaces of gravestones.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-vaccination', 'reading', 'Edward Jenner and the Origins of Vaccination', 'By the late eighteenth century, smallpox killed an estimated ten percent of the population in some European countries during major outbreaks, and it left many survivors permanently scarred or blind. Physicians had long practiced variolation, a risky method of deliberately exposing healthy people to material from smallpox sores to induce a milder case of the disease, but variolation itself sometimes caused fatal infections and could spread the disease further. Rural folklore, meanwhile, held that milkmaids who had previously caught cowpox, a much milder disease affecting cattle, rarely contracted smallpox at all.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-industrial-urbanization', 'reading', 'Urbanization During the Industrial Revolution', 'Before the Industrial Revolution, most people in Britain lived in small rural villages and made their living from agriculture or small-scale craft production. The introduction of mechanized textile manufacturing and the growing use of steam power in the late eighteenth and early nineteenth centuries changed this pattern dramatically, as factories requiring large numbers of workers and steady access to coal and transportation networks tended to concentrate in and around a small number of towns. Manchester, for example, grew from a modest market town of about twenty-five thousand people in 1770 to a city of several hundred thousand within a few decades.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-echolocation', 'reading', 'Echolocation in Bats', 'Most bat species navigate and hunt not primarily by sight but by echolocation, a biological sonar system in which the animal emits high-frequency sound pulses, often well above the range of human hearing, and interprets the echoes that bounce back from objects in the environment. By analyzing tiny differences in the timing, intensity, and frequency of these returning echoes, a bat can determine not just the distance and direction of an object but also, with remarkable precision, its size, shape, texture, and even whether it is moving.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-panama-canal', 'reading', 'The Construction of the Panama Canal', 'French engineers, led by Ferdinand de Lesseps, who had earlier overseen construction of the Suez Canal, began work on a canal across the Isthmus of Panama in 1881, attempting to build a sea-level waterway similar to the one at Suez. The project collapsed within a decade, defeated by a combination of financial mismanagement, unstable mountainous terrain, and, most devastatingly, disease: malaria and yellow fever killed an estimated twenty thousand workers, since the connection between these diseases and mosquitoes was not yet understood.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-cognitive-dissonance', 'reading', 'Cognitive Dissonance Theory', 'In the 1950s, psychologist Leon Festinger proposed that people experience a distinctly uncomfortable mental state, which he termed cognitive dissonance, whenever they simultaneously hold two beliefs, or a belief and a behavior, that contradict one another. According to Festinger, this discomfort is not merely unpleasant but actively motivating: people are driven to reduce the inconsistency, often without being fully aware they are doing so.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-desert-adaptations', 'reading', 'Adaptations to Desert Ecosystems', 'Deserts are defined not by heat alone but by extreme scarcity of precipitation, typically receiving less than 250 millimeters of rain per year, combined with dramatic swings in temperature between day and night due to the absence of moisture and cloud cover that would otherwise moderate the climate. Organisms that live in deserts must therefore cope with two related challenges simultaneously: severe water scarcity and thermal extremes that can range from scorching daytime heat to near-freezing nighttime cold.
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c01', 'structure', NULL, 'structure_completion', '_____ the mission was originally scheduled for launch in March, technical problems delayed it until June.', '["Although","Despite","Because of","In spite"]', 0, '後ろに従属節が続いているため、"Although" のような従属接続詞が必要です。"Despite" や "In spite (of)" は節ではなく名詞句を伴い、"Because of" では意味が逆になってしまいます。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c02', 'structure', NULL, 'structure_completion', 'Not until the twentieth century _____ widely available to ordinary households.', '["electricity became","did electricity become","electricity did become","had electricity become"]', 1, '文頭に "Not until..." が来ると主語と助動詞の倒置が起こり、"did + 主語 + 動詞の原形" の語順になります。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c03', 'structure', NULL, 'structure_completion', 'The committee requested that the report _____ before the end of the fiscal year.', '["is submitted","submitted","be submitted","will be submitted"]', 2, '"request that" は仮定法現在を要求する動詞で、時制に関係なく原形の "be submitted" を使います。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c04', 'structure', NULL, 'structure_completion', '_____ of the two candidates has the experience necessary to lead the department.', '["Neither","None","Both","All"]', 0, '"neither" はちょうど2つのものについて使い、"none" は3つ以上の場合に使います。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c05', 'structure', NULL, 'structure_completion', 'The museum''s new wing, _____ construction took nearly three years, opens to the public next month.', '["which","whose","that","who"]', 1, '「建設(工事)」が「新館」に属することを示すには所有格の関係代名詞が必要で、"whose" は人にも物にも使えます。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c06', 'structure', NULL, 'structure_completion', 'It is essential that every employee _____ the updated safety guidelines before returning to the factory floor.', '["reviews","review","reviewing","will review"]', 1, '"It is essential that" の後には仮定法現在の原形 "review" が必要です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c07', 'structure', NULL, 'structure_completion', '_____ increasing air travel, many small regional airports have struggled to remain profitable.', '["Despite","Although","However","Nevertheless"]', 0, '後ろに名詞句("increasing air travel")が続いているため、接続詞や副詞ではなく "Despite" のような前置詞が必要です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c08', 'structure', NULL, 'structure_completion', 'The new bridge is _____ than the one it replaced, allowing much heavier trucks to cross safely.', '["more strong","stronger","as strong","the strongest"]', 1, '"strong" のような1音節の形容詞は "more" ではなく "-er" を付けて比較級を作ります。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c09', 'structure', NULL, 'structure_completion', 'Rarely _____ such a well-preserved fossil found outside a controlled excavation site.', '["is","has been","it is","being"]', 1, '否定的な意味を持つ副詞 "Rarely" が文頭に来ると倒置が起こり、"has + 主語 + been" の語順になります。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c10', 'structure', NULL, 'structure_completion', 'The scientist explained _____ the experiment had failed.', '["why did","why","that why","the reason why did"]', 1, '間接疑問文(埋め込み疑問文)では疑問詞の倒置は起こらず、通常の語順を使います。したがって "explained why the experiment had failed" となります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c11', 'structure', NULL, 'structure_completion', '_____ to reduce costs, the airline eliminated several unprofitable routes.', '["In an effort","With an effort","By effort","For efforts"]', 0, '"in an effort to + 動詞" は "in order to"(〜するために)と同じ意味を表す定型表現です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c12', 'structure', NULL, 'structure_completion', 'The data collected during the survey _____ far more comprehensive than researchers had expected.', '["were","was","are","have been"]', 0, '"data" は "datum" の複数形であり、日常会話では単数扱いされることも多いですが、フォーマルな英語(試験で問われる英語)では複数動詞 "were" を取ります。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c13', 'structure', NULL, 'structure_completion', 'If the bridge _____ properly maintained, the collapse could have been prevented.', '["was","were","had been","has been"]', 2, 'これは過去の事実に反する仮定を表す仮定法過去完了(第3条件文)で、"could have been prevented" に対応するif節には "had been" が必要です。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c14', 'structure', NULL, 'structure_completion', 'Only after the results were independently verified _____ the findings for publication.', '["the team accepted","did the team accept","the team did accept","had the team accepted"]', 1, '文頭に "Only after..." が来ると主節で主語と助動詞の倒置が起こり、"did + 主語 + 動詞の原形" の語順になります。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c15', 'structure', NULL, 'structure_completion', 'The new regulation applies to _____ manufacturers importing goods into the country.', '["all","every","each","all of"]', 0, '"all" は複数名詞 "manufacturers" を正しく修飾できます。"every" と "each" は単数名詞を必要とし、"all of" を使うなら名詞の前に "the" が必要です。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c16', 'structure', NULL, 'structure_completion', 'The lecture covered not only the causes of the recession _____ also its long-term effects on employment.', '["but","and","or","so"]', 0, '"not only... but also..."(〜だけでなく…も)は決まった相関接続詞のペアです。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c17', 'structure', NULL, 'structure_completion', 'The professor recommended _____ the assignment before attending the seminar.', '["to complete","completing","complete","completion"]', 1, '"recommend" の後には不定詞ではなく動名詞("completing")が続きます。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c18', 'structure', NULL, 'structure_completion', '_____ the report is finished, the team will begin drafting the next proposal.', '["Until","Once","Unless","Since"]', 1, '"once" は「〜するとすぐに」という意味で、報告書を終えてから次の作業に取りかかるという時間的な流れに合います。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c19', 'structure', NULL, 'structure_completion', 'The findings of the two studies, though conducted independently, _____ remarkably similar.', '["is","was","are","has been"]', 2, '主語 "findings" は複数形なので、現在形の動詞は "are" でなければなりません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c20', 'structure', NULL, 'structure_completion', 'The city council debated whether the new stadium _____ funded through public bonds or private investment.', '["should be","should","should being","is should be"]', 0, '"whether" の後には受動態の助動詞構文 "should be funded" が必要です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c21', 'structure', NULL, 'structure_completion', 'The committee has yet _____ a final decision on the merger.', '["to make","making","make","made"]', 0, '"has yet to + 動詞の原形" は「まだ〜していない」という意味を表す定型表現です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c22', 'structure', NULL, 'structure_completion', 'The more data scientists collected, _____ their models became.', '["more accurate","the more accurate","accurate","most accurate"]', 1, '"the more..., the more..."(〜すればするほど…)という相関比較構文では、両方の比較級の前に "the" が必要です。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c23', 'structure', NULL, 'structure_completion', 'The manuscript, along with the accompanying illustrations, _____ donated to the university library.', '["were","was","have been","are"]', 1, '"along with the accompanying illustrations" は挿入句であり、動詞は単数主語 "manuscript" に一致させて "was" にする必要があります。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c24', 'structure', NULL, 'structure_completion', 'Few of the witnesses _____ willing to testify in court.', '["was","is","were","has been"]', 2, '"few" は複数扱いの数量詞なので、動詞も複数形の "were" にする必要があります。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e01', 'structure', NULL, 'structure_error_id', 'The results of the study, which was published last year, suggest that the new treatment is more effective than previously believed.', '["which was published last year","suggest that the new treatment","is more effective than","previously believed"]', 0, '関係代名詞 "which" は複数形の "results" を指しているため、動詞は "was" ではなく "were" にする必要があります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e02', 'structure', NULL, 'structure_error_id', 'Despite their initial success, the company''s profits have steady declined over the past three years.', '["their initial success","the company''s profits","have steady declined","over the past three years"]', 2, '動詞 "declined" を修飾するには形容詞 "steady" ではなく副詞 "steadily" を使う必要があります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e03', 'structure', NULL, 'structure_error_id', 'Each of the applicants were required to submit a portfolio along with a letter of recommendation.', '["were required to","submit a portfolio","along with","a letter of recommendation"]', 0, '"each of the applicants" は文法上単数扱いなので、動詞は "were required" ではなく "was required" にする必要があります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e04', 'structure', NULL, 'structure_error_id', 'The number of students enrolling in online courses have risen sharply since the university expanded its remote offerings.', '["enrolling in online courses","have risen sharply","since the university","expanded its remote offerings"]', 1, '"the number of" は単数動詞("has risen")を取ります。複数動詞を取る "a number of" とは異なるので注意が必要です。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e05', 'structure', NULL, 'structure_error_id', 'Scientists have long debated whether Pluto should be classify as a planet or a dwarf planet.', '["whether Pluto should","be classify as","a planet or","a dwarf planet"]', 1, '助動詞 "should" の後には受動態の原形 "be classified" が必要で、"be classify" という形は誤りです。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e06', 'structure', NULL, 'structure_error_id', 'The recipe calls for two cups of flour, a teaspoon of salt, and beating the eggs until frothy.', '["two cups of flour","a teaspoon of salt","beating the eggs","until frothy"]', 2, 'リストの列挙は名詞句として並列("two cups of flour"、"a teaspoon of salt"、"two beaten eggs")にそろえる必要がありますが、"beating the eggs" だけ動名詞句になっており、パラレリズム(並列構造)が崩れています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e07', 'structure', NULL, 'structure_error_id', 'Although the medication reduced her symptoms, it also caused several side effect that concerned her doctor.', '["reduced her symptoms","it also caused","several side effect","that concerned her doctor"]', 2, '数量詞 "several" の後には複数名詞が必要なので、"several side effect" ではなく "several side effects" が正しい形です。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e08', 'structure', NULL, 'structure_error_id', 'By the time the film crew arrived, the storm had already destroy much of the coastal village''s fishing fleet.', '["the storm had already","destroy much of","the coastal village''s","fishing fleet"]', 1, '過去完了形では原形の "destroy" ではなく過去分詞を使った "had already destroyed" にする必要があります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e09', 'structure', NULL, 'structure_error_id', 'The findings, which was presented at the conference, challenged decades of prior research on the subject.', '["which was presented at the conference","challenged decades of","prior research","on the subject"]', 0, '関係代名詞 "which" は複数形の "findings" を指しているため、動詞は "was" ではなく "were" にする必要があります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e10', 'structure', NULL, 'structure_error_id', 'The engineers worked quick to repair the damaged pipeline before the storm arrived.', '["worked quick to repair","the damaged pipeline","before the storm","arrived"]', 0, '動詞 "worked" を修飾するには形容詞 "quick" ではなく副詞 "quickly" を使う必要があります。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e11', 'structure', NULL, 'structure_error_id', 'The committee is responsible to ensure that all safety protocols are strictly followed during construction.', '["is responsible to ensure","that all safety protocols","are strictly followed","during construction"]', 0, '正しい表現は "responsible to ensure" ではなく "responsible for ensuring" です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e12', 'structure', NULL, 'structure_error_id', 'Of the two proposals, the second one is more preferable because it costs less to implement.', '["Of the two proposals","the second one is more preferable","because it costs less","to implement"]', 1, '"preferable" はそれ自体に比較の意味(「より望ましい」)が含まれているため、"more" を付けるのは冗長です。単に "preferable" とすべきです。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e13', 'structure', NULL, 'structure_error_id', 'By next year, the company will completed the transition to renewable energy sources.', '["By next year","the company will completed","the transition to","renewable energy sources"]', 1, '"by next year" は未来のある時点までに完了している動作を示すため、未来完了形 "will have completed" が必要です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e14', 'structure', NULL, 'structure_error_id', 'The workshop taught participants how to write clearly, organize their arguments, and to present with confidence.', '["how to write clearly","organize their arguments","and to present","with confidence"]', 2, 'リストは "write"、"organize"、"present" という並列構造を保つべきですが、"to present" だけ "to" を繰り返しており、パラレリズムが崩れています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e15', 'structure', NULL, 'structure_error_id', 'There has been several complaints filed against the company this month.', '["There has been","several complaints","filed against","the company this month"]', 0, '主語 "complaints" は複数形なので、there構文では "There has been" ではなく "There have been" が必要です。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e16', 'structure', NULL, 'structure_error_id', 'Fewer rainfall this year has led to a severe drought across the region.', '["Fewer rainfall this year","has led","to a severe drought","across the region"]', 0, '"rainfall" は不可算名詞なので、可算名詞に使う "fewer" ではなく "less" で修飾する必要があります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c25', 'structure', NULL, 'structure_completion', 'The book _____ on the table belongs to my sister.', '["lying","lay","lied","is lying"]', 0, '「book」を後ろから修飾する分詞構文(縮約関係詞節)なので、自動詞「lie(横たわる・置いてある)」の現在分詞「lying」が正解です。「lay」「lied」は定形動詞(文の述語になる形)であり、名詞を後置修飾する形にはなりません。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c26', 'structure', NULL, 'structure_completion', '_____ several times, the manuscript was finally accepted for publication.', '["Revising","Having revised","Revised","To revise"]', 2, '「原稿(manuscript)」は「改訂する」のではなく「改訂される」側なので、受け身の過去分詞「Revised」が正解です。「Revising」や「Having revised」は能動の意味になってしまい、主語(原稿)と意味が合いません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c27', 'structure', NULL, 'structure_completion', '_____ finished her research, she began writing the final report.', '["Having","Have","To have","Had"]', 0, '「Having + 過去分詞」(完了分詞構文)は、主節の動作より前に完了した動作を表します。「Have」「To have」「Had」はこのような分詞構文の形を作れません。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c28', 'structure', NULL, 'structure_completion', 'The new library _____ by the city council since 2019.', '["has been funded","is funding","funds","had funding"]', 0, '「since 2019」があることから、資金提供は過去に始まり現在まで続いていることがわかります。また図書館は「資金を提供される」側なので、現在完了の受動態「has been funded」が正解です。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c29', 'structure', NULL, 'structure_completion', 'The proposal _____ by the board before the end of the quarter.', '["will review","will be reviewed","reviews","is reviewing"]', 1, '「提案書(proposal)」は「審査する」のではなく「審査される」側なので受け身が必要です。未来の受け身を正しく表す「will be reviewed」が正解です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c30', 'structure', NULL, 'structure_completion', 'If it _____ tomorrow, the outdoor ceremony will be moved indoors.', '["rains","will rain","rained","would rain"]', 0, '現実に起こりうる未来の出来事を述べる「第1条件文」では、if節の中は現在形(rains)を使い、主節でwillを使います。if節の中では未来形(will rain)は使いません。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c31', 'structure', NULL, 'structure_completion', 'If the company _____ more resources into research, it would likely develop new products faster.', '["puts","put","will put","had put"]', 1, '主節が「would likely develop」となっていることから、現在の事実に反する仮定を表す「第2条件文」だとわかります。第2条件文のif節では動詞は過去形(put)を使います。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c32', 'structure', NULL, 'structure_completion', 'The interviewer asked the candidate _____ she had chosen to leave her previous job.', '["why did","why","why had","that why"]', 1, '他の文に組み込まれた間接疑問文では、疑問詞のあとは通常の平叙文の語順(主語+動詞)になります。「why she had chosen」が正しく、疑問文のような倒置(why did she)は間接疑問文では使いません。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c33', 'structure', NULL, 'structure_completion', 'The city has invested _____ money in improving public transportation this year.', '["many","much","a number of","few"]', 1, '「money(お金)」は不可算名詞なので、可算名詞に使う「many」「a number of」「few」ではなく、不可算名詞を修飾する「much」を使います。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c34', 'structure', NULL, 'structure_completion', '_____ effort went into designing the new bridge to withstand earthquakes.', '["A great deal of","A great number of","Many","Few"]', 0, '「effort(努力)」は不可算名詞なので、不可算名詞に使う数量表現「a great deal of」が正解です。「a great number of」「many」「few」はいずれも可算名詞に使う表現です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c35', 'structure', NULL, 'structure_completion', 'The meeting is scheduled _____ 3 p.m. on Thursday.', '["in","on","at","by"]', 2, '「3 p.m.」のような時刻を表すときには前置詞「at」を使います(例: at 3 p.m.)。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c36', 'structure', NULL, 'structure_completion', 'The company''s headquarters are located _____ the corner of Fifth Avenue and Main Street.', '["in","at","on","by"]', 1, '交差点の場所を表すときの決まった言い方は「at the corner of」です。この熟語をそのまま覚えておきましょう。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c37', 'structure', NULL, 'structure_completion', 'The committee''s decision was based _____ extensive research and community feedback.', '["in","on","at","for"]', 1, '「〜に基づいている」という意味の正しい連語(コロケーション)は「based on」です。この組み合わせで覚えておく必要があります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c38', 'structure', NULL, 'structure_completion', 'The professor''s argument consists _____ three main points, each supported by data.', '["of","in","with","from"]', 0, '「〜から成る、〜で構成されている」という意味の正しい連語は「consist of」です。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c39', 'structure', NULL, 'structure_completion', 'The scientist reported that the results _____ significant implications for future research.', '["have","had","has","will have"]', 1, '伝達動詞(ここではreported)が過去形の場合、that節の中の時制もそれに合わせて一つ過去にずらす「時制の一致」が起こります。そのため現在形「have」ではなく過去形「had」を使います。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c40', 'structure', NULL, 'structure_completion', 'The evidence was _____ compelling that the jury reached a verdict within an hour.', '["so","such","too","very"]', 0, '原因と結果を表す「so + 形容詞 + that」の構文が正解です。「such」を使う場合は「such compelling evidence」のように名詞句が必要になります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c41', 'structure', NULL, 'structure_completion', 'It was _____ a persuasive argument that even the skeptics were convinced.', '["so","such","too","very"]', 1, '後ろに名詞(argument)が続く場合は「such + a/an + 形容詞 + 名詞 + that」の形を使います。「so」を使う場合は冠詞と名詞を省いて「so persuasive that」のようにします。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c42', 'structure', NULL, 'structure_completion', 'Before the factory closed, workers _____ commute over an hour each way.', '["use to","used to","are used to","get used to"]', 1, '「used to + 動詞の原形」は「以前はよく〜したものだ(今はもうしていない)」という過去の習慣を表します。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c43', 'structure', NULL, 'structure_completion', 'After years abroad, she _____ living in a different time zone from her family.', '["used to","use to","is used to","uses to"]', 2, '「be used to + 動名詞/名詞」は「〜に慣れている」という意味で、ここでは「異なる時差の中で暮らすことに慣れている」という継続的な状態に合います。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c44', 'structure', NULL, 'structure_completion', 'It took the new employees several weeks to _____ the company''s strict dress code.', '["use to","get used to","used to","be use to"]', 1, '「get used to + 動名詞/名詞」は「〜に慣れていく」という変化の過程を表し、「数週間かかった」という文脈にぴったり合います。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c45', 'structure', NULL, 'structure_completion', 'The homeowners decided to _____ the roof repaired before the rainy season began.', '["have","make","let","get to"]', 0, '使役表現「have + 目的語 + 過去分詞」は「(人に頼んで)〜してもらう」という意味です。屋根の修理を業者に依頼する、という状況に合います。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c46', 'structure', NULL, 'structure_completion', 'The manager arranged to _____ the contract reviewed by the legal department before signing.', '["have get","get","make","let"]', 1, '使役表現「get + 目的語 + 過去分詞」も「〜してもらう」という意味を表し、ここではこの受け身的な使役の形に合うのは「get」だけです。他の選択肢はこの形に当てはまりません。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c47', 'structure', NULL, 'structure_completion', '_____ patience is essential for anyone learning a new language.', '["The","A","An","(no article)"]', 3, '「patience(忍耐力)」のような抽象的な性質・概念を一般的な意味で述べるときには、冠詞をつけません。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c48', 'structure', NULL, 'structure_completion', '_____ Amazon River carries more water than any other river in the world.', '["A","An","The","(no article)"]', 2, '河川名には定冠詞「the」をつけるという決まりがあります(例: the Amazon River)。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c49', 'structure', NULL, 'structure_completion', 'It is crucial that the medication _____ refrigerated at all times.', '["is","be","will be","being"]', 1, '「It is crucial that」に続くthat節の中では、時制に関係なく動詞の原形(仮定法現在)を使います。ここでは受け身の原形「be refrigerated」が正解です。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c50', 'structure', NULL, 'structure_completion', 'Dr. Elena Cruz, _____ of the research team, presented the findings at the symposium.', '["the leader","leading","who leads","leads"]', 0, 'コンマで挟まれ、主語を別の言葉で言い換える「同格」の部分には名詞句が入ります。「the leader(リーダー)」という名詞句が正解です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c51', 'structure', NULL, 'structure_completion', 'Although the results seemed inconclusive at first, the data _____ support the original hypothesis.', '["does","did","is","was"]', 1, '強調の助動詞「did」を動詞の原形「support」と組み合わせることで、「seemed inconclusive(結論が出ていないように見えた)」との対比を強めています。文脈は過去の話なので、現在形かつ単数用法の「does」は合いません。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c52', 'structure', NULL, 'structure_completion', '_____ was the unexpected drop in temperature that caused the pipes to freeze overnight.', '["It","There","This","That"]', 0, '「It was X that ...」という強調構文(分裂文)で、「the unexpected drop in temperature(予想外の気温低下)」を強調しています。この構文の主語は必ず「It」になります。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c53', 'structure', NULL, 'structure_completion', '_____ the committee approved the budget came as a relief to the entire department.', '["What","That","Which","Because"]', 1, '「That」は文の主語になれる名詞節を導くことができます。「What」だと意味が変わってしまい、「Which」は先行詞が必要で、「Because」が導く副詞節は文の主語にはなれません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c54', 'structure', NULL, 'structure_completion', 'The workers arrived early _____ finish the project before the deadline.', '["so as","in order to","for to","so that"]', 1, '目的を表す「in order to + 動詞の原形」が正解です。「so as」は単独では不完全な形であり、「for to」は正しい英語ではなく、「so that」の後には不定詞ではなく完全な節が必要です。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c55', 'structure', NULL, 'structure_completion', 'The teacher spoke slowly _____ all the students could understand the instructions.', '["so that","so as to","in order","for"]', 0, '後ろに主語と動詞を含む完全な節が続く場合、目的を表すには「so that + 節」を使います。「so as to」や「in order」の後には不定詞が続き、節は続きません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c56', 'structure', NULL, 'structure_completion', '_____ the weather improves, the outdoor concert will likely be canceled due to the flood damage.', '["Even though","Even if","Because","Unless"]', 1, '「Even if」は「たとえ〜だとしても」と、まだ不確かな仮定の状況を導きます。この文脈は仮定的な内容なので合いますが、「Even though」は既に分かっている事実に対して使うため合いません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c57', 'structure', NULL, 'structure_completion', '_____ the team had prepared thoroughly, the presentation did not go as planned.', '["Despite","Despite the fact that","Despite of","In spite"]', 1, '後ろに主語と動詞を含む完全な節が続く場合は「Despite the fact that」を使います。「Despite」単独、「Despite of」、「of」を伴わない「In spite」は、いずれも節を直接後ろに置くことができません。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c58', 'structure', NULL, 'structure_completion', 'The engineers reinforced the dam _____ it collapse during the flood season.', '["lest","unless","in case of","so"]', 0, '「lest」は「〜しないように」という意味のややかたい接続詞で、後ろには仮定法現在(動詞の原形)である「collapse」が続きます。望ましくない事態を未然に防ぐ、という意味を表しています。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c59', 'structure', NULL, 'structure_completion', 'The northern region relies heavily on manufacturing, _____ the southern region depends primarily on agriculture.', '["whereas","despite","unless","because"]', 0, '「whereas(〜である一方)」は2つの事実を対比するときに使います。2つの地域の経済構造を比較しているこの文脈にぴったり合います。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c60', 'structure', NULL, 'structure_completion', 'The old house looked as if it _____ abandoned for decades.', '["is","was","had been","has been"]', 2, '「as if / as though」が、見た瞬間よりも前に起きた出来事の結果としての状態を表す場合には、過去完了形「had been abandoned」を使います。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c61', 'structure', NULL, 'structure_completion', 'I wish I _____ more time to prepare for the exam.', '["have","had","will have","has"]', 1, '「wish」を使って現在の事実に反する願望を表す場合、意味は現在のことでも動詞は過去形(仮定法過去)「had」を使います。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c62', 'structure', NULL, 'structure_completion', 'The manager would rather the report _____ submitted by Friday instead of Monday.', '["is","will be","were","be"]', 2, '「would rather + 主語 + 動詞」の形は、主語が話し手自身の動作ではない場合に使い、動詞には仮定法過去(were submitted)を使います。「is」「will be」「be」はこの構文には合いません。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c63', 'structure', NULL, 'structure_completion', 'It''s time the company _____ its outdated policies.', '["updates","update","updated","will update"]', 2, '「It''s time + 主語 + 過去形」は「そろそろ〜すべき時だ、〜するのが遅すぎるくらいだ」という意味を表す仮定法的な決まり文句で、動詞には過去形「updated」を使います。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c64', 'structure', NULL, 'structure_completion', 'The organization has supported local schools _____ over two decades.', '["since","for","during","from"]', 1, '「for」は「for over two decades(20年以上にわたって)」のように期間の長さを表すときに使います。一方「since」は起点となる時点を表すときに使います。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e17', 'structure', NULL, 'structure_error_id', 'The new policy will effect how employees schedule their vacation time next year.', '["The new policy will effect","how employees schedule","their vacation time","next year"]', 0, 'ここでは「〜に影響を与える」という意味の動詞"affect"が必要だが、通常は名詞として使われる"effect"になっている。"effect"を動詞として使うと「〜を引き起こす」という意味になり、この文の意図に合わない。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e18', 'structure', NULL, 'structure_error_id', 'The inheritance was divided between the four siblings according to their father''s will.', '["The inheritance was divided","between the four siblings","according to","their father''s will"]', 1, '"between"は2者の間を表すときに使う語。ここでは4人のきょうだいのように3者以上が対象になっているので、"among"を使う必要がある。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e19', 'structure', NULL, 'structure_error_id', 'After the long hike, she decided to lay down and rest for a while before continuing.', '["After the long hike,","she decided to lay down","and rest for a while","before continuing"]', 1, '「横になる」という意味の自動詞"lie"(lie–lay–lain)が必要。"lay"は他動詞で目的語を取る動詞なので、ここでは使えない。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e20', 'structure', NULL, 'structure_error_id', 'Since the merger was completed, the two companies shared a single headquarters in the capital.', '["Since the merger was completed,","the two companies","shared a single headquarters","in the capital"]', 2, '"since"で始まり、現在まで続く状態を表す節では現在完了形("have shared")を使う必要があり、単純過去形の"shared"は誤り。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e21', 'structure', NULL, 'structure_error_id', 'Arriving late to the meeting, the presentation had already begun without him.', '["Arriving late to the meeting,","the presentation had","already begun","without him"]', 1, '文頭の分詞構文"Arriving late to the meeting"は意味の上で人を修飾するはずだが、主節の主語が"the presentation"になっており、修飾先が宙に浮いた「懸垂分詞構文」になっている。主語は人にする必要がある(例:"he had already begun")。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e22', 'structure', NULL, 'structure_error_id', 'The committee are meeting tomorrow to discuss the new budget proposal.', '["The committee are meeting","tomorrow to discuss","the new budget","proposal"]', 0, '標準的なアメリカ英語では、"committee"のような集合名詞が1つのまとまりとして機能する場合は単数扱いの動詞を取るため、"The committee is meeting"が正しい。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e23', 'structure', NULL, 'structure_error_id', 'Drivers should avoid to use their phones while operating a vehicle.', '["Drivers should avoid","to use their phones","while operating","a vehicle"]', 1, '"avoid"の後には不定詞ではなく動名詞が続く。したがって"avoid to use"ではなく"avoid using"が正しい。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e24', 'structure', NULL, 'structure_error_id', 'Many students are interested on studying abroad during their junior year.', '["Many students are","interested on studying","abroad during","their junior year"]', 1, '"interested"の後に続く正しい前置詞は"on"ではなく"in"("interested in studying")。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e25', 'structure', NULL, 'structure_error_id', 'This year''s exam was more harder than last year''s, according to most students.', '["This year''s exam","was more harder than","last year''s,","according to most students"]', 1, '"harder"はすでに"hard"の比較級なので、さらに"more"を付けると二重比較級になってしまう。単に"harder than"とすればよい。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e26', 'structure', NULL, 'structure_error_id', 'She received an unique opportunity to study at the research institute.', '["She received","an unique opportunity","to study at","the research institute"]', 1, '"unique"は子音の音(「ユニーク」)で始まるため、前に置く冠詞は"an"ではなく"a"になる("a unique opportunity")。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e27', 'structure', NULL, 'structure_error_id', 'The bridge was closed for repairs, however commuters found alternate routes without much difficulty.', '["The bridge was closed","for repairs, however","commuters found alternate routes","without much difficulty"]', 1, '"however"だけでは2つの独立した節をコンマでつなぐことはできない。前にセミコロンを置くか("for repairs; however,")、2つの文に分ける必要がある。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e28', 'structure', NULL, 'structure_error_id', 'The new bridge is being build by a team of engineers from three different countries.', '["The new bridge","is being build by","a team of engineers","from three different countries"]', 1, '受動進行形には過去分詞"built"が必要で、原形の"build"は使えない("is being built")。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e29', 'structure', NULL, 'structure_error_id', 'The laptop who crashed during the presentation had never malfunctioned before.', '["The laptop who crashed","during the presentation","had never","malfunctioned before"]', 0, '"who"は人を指す関係代名詞。"laptop"は物なので、関係代名詞には"that"または"which"を使う必要がある("The laptop that crashed")。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e30', 'structure', NULL, 'structure_error_id', 'The witness couldn''t hardly remember any details about the incident that night.', '["The witness couldn''t hardly","remember any details","about the incident","that night"]', 0, '"hardly"はそれ自体が否定的な意味を持つ語なので、"couldn''t"と組み合わせると二重否定になってしまう。正しくは"could hardly remember"。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e31', 'structure', NULL, 'structure_error_id', 'The manager and the supervisor is responsible for approving the new hires.', '["The manager and the supervisor","is responsible for","approving the new","hires"]', 1, '"and"で結ばれた複合主語("The manager and the supervisor")は複数として扱われるため、動詞は"is responsible"ではなく"are responsible"が正しい。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e32', 'structure', NULL, 'structure_error_id', 'The coach made the players to run extra laps after they arrived late to practice.', '["The coach made","the players to run","extra laps after","they arrived late to practice"]', 1, '使役動詞"make"の後には"to"を伴わない原形の動詞(原形不定詞)が続く。したがって"made the players to run"ではなく"made the players run"が正しい。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e33', 'structure', NULL, 'structure_error_id', 'The organization revised it''s membership policy after receiving feedback from long-time members.', '["The organization revised","it''s membership policy","after receiving feedback","from long-time members"]', 1, '"it"の所有格は"its"(アポストロフィなし)。"it''s"は"it is"の短縮形であり、ここでは意味が合わない。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e34', 'structure', NULL, 'structure_error_id', 'Either the manager or the employees is responsible for submitting the report on time.', '["Either the manager","or the employees","is responsible for","submitting the report on time"]', 2, '"either...or"では、動詞は"or"に近い方の主語に一致させる。ここでは近い主語が複数形の"employees"なので、"are responsible"が正しい。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e35', 'structure', NULL, 'structure_error_id', 'I would rather to stay home tonight than go to the crowded concert.', '["I would rather to stay","home tonight","than go to","the crowded concert"]', 0, '"would rather"の直後には"to"を伴わない動詞の原形が続く。したがって"would rather to stay"ではなく"would rather stay"が正しい。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e36', 'structure', NULL, 'structure_error_id', 'Please let me know who you will invite to the ceremony next month.', '["Please let me know","who you will invite","to the ceremony","next month"]', 1, 'この代名詞は"invite"の目的語として機能している(you will invite whom)ため、フォーマルな文章では主格の"who"ではなく目的格の"whom"が必要になる。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e37', 'structure', NULL, 'structure_error_id', 'The reason the flight was delayed is because of a mechanical issue with the aircraft.', '["The reason the flight","was delayed is because of","a mechanical issue","with the aircraft"]', 1, '"the reason is because"は"reason"と"because"がどちらも原因を表すため、意味が重複してしまう。"the reason...is that"とするか、単に"the flight was delayed because of"とするのが正しい。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e38', 'structure', NULL, 'structure_error_id', 'When I arrive at the airport yesterday, my flight had already been delayed by two hours.', '["When I arrive","at the airport yesterday,","my flight had already","been delayed by two hours"]', 0, 'この時を表す節は"yesterday"という過去に完了した出来事を指しているため、動詞は単純過去形でなければならない("When I arrived")。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e39', 'structure', NULL, 'structure_error_id', 'She is one of the few employees who consistently meets every deadline without exception.', '["She is one of","the few employees","who consistently meets","every deadline without exception"]', 2, '関係代名詞"who"は複数名詞"employees"を指しているため、動詞も複数形の"meet"にする必要があり、"meets"は誤り。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e40', 'structure', NULL, 'structure_error_id', 'The new engine is not as efficient than the previous model in terms of fuel consumption.', '["The new engine","is not as efficient than","the previous model","in terms of fuel consumption"]', 1, '"as...as"の構文は同等比較を表すため両側に"as"が必要で、"than"は使えない。正しくは"not as efficient as the previous model"。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e41', 'structure', NULL, 'structure_error_id', 'During the interview, the candidate acted very professional despite being nervous.', '["During the interview,","the candidate acted","very professional","despite being nervous"]', 2, 'ここでの動詞"acted"は様態(どのように振る舞ったか)を表しているため、形容詞"professional"ではなく副詞"professionally"で修飾する必要がある。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e42', 'structure', NULL, 'structure_error_id', 'Collecting rare stamps have been her hobby since she was a child.', '["Collecting rare stamps","have been her hobby","since she was","a child"]', 1, '主語として機能する動名詞句("Collecting rare stamps")は単数として扱われるため、動詞は"have been"ではなく"has been"が正しい。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e43', 'structure', NULL, 'structure_error_id', 'She use to walk to school every morning before her family bought a car.', '["She use to walk","to school every morning","before her family","bought a car"]', 0, '過去の習慣を表す表現には"use to"ではなく"used to"が必要("She used to walk")。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e44', 'structure', NULL, 'structure_error_id', 'There is a wallet and several keys underneath the front seat of the car.', '["There is a wallet","and several keys","underneath the front seat","of the car"]', 0, '"there"の後に続く主語は複合主語"a wallet and several keys"であり複数扱いになるため、"There is"ではなく"There are"が正しい。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e45', 'structure', NULL, 'structure_error_id', 'The results of this experiment are similar with those reported in earlier studies.', '["The results of","this experiment are","similar with those reported","in earlier studies"]', 2, '正しい慣用表現は"similar with"ではなく"similar to"("similar to those reported")。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e46', 'structure', NULL, 'structure_error_id', 'Each and every one of the applicants were interviewed twice before a decision was made.', '["Each and every one","of the applicants were interviewed","twice before","a decision was made"]', 1, '"each and every one"は文法上単数として扱われるため、動詞は"were interviewed"ではなく"was interviewed"が正しい。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e47', 'structure', NULL, 'structure_error_id', 'If the government increases funding for public transit, more people would use the buses instead of driving.', '["If the government increases","funding for public transit,","more people would use","the buses instead of driving"]', 0, '主節に仮定を表す"would use"が使われており、これは第二条件文(仮定法過去)のif節と対応する形。したがって"increases"ではなく過去形の"If the government increased"にしないと時制が一致しない。', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e48', 'structure', NULL, 'structure_error_id', 'Beside working as a nurse, she volunteers at an animal shelter every weekend.', '["Beside working as a nurse,","she volunteers at","an animal shelter","every weekend"]', 0, '「〜に加えて」という意味の"besides"が必要で、「〜の隣に」という意味の"beside"はここでは意味が合わない("Besides working as a nurse")。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e49', 'structure', NULL, 'structure_error_id', 'Prices have raised steadily over the past decade due to inflation.', '["Prices have raised","steadily over","the past decade","due to inflation"]', 0, '"rise"は物事がひとりでに増加することを表す自動詞(rise–rose–risen)。"raise"は他動詞で目的語を必要とするため、ここでは"Prices have risen"が正しい。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e50', 'structure', NULL, 'structure_error_id', 'Could you borrow me your calculator for the duration of the exam?', '["Could you borrow me","your calculator","for the duration","of the exam"]', 0, '"lend"は何かを一時的に「貸す」こと、"borrow"は何かを一時的に「借りる」ことを意味する。話し手は電卓を借りたい側なので、"Could you lend me"が正しい。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e51', 'structure', NULL, 'structure_error_id', 'The news about the merger were leaked to journalists before the official announcement.', '["The news about","the merger were leaked","to journalists before","the official announcement"]', 1, '"news"は常に単数扱いとなる不可算名詞なので、"were leaked"ではなく"the news...was leaked"が正しい。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e52', 'structure', NULL, 'structure_error_id', 'It was so complicated problem that even the professor took an hour to solve it.', '["It was so complicated problem","that even the professor","took an hour","to solve it"]', 0, '名詞の前では"so"ではなく"such a/an + 形容詞 + 名詞"の形を使う。正しくは"It was such a complicated problem"。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e53', 'structure', NULL, 'structure_error_id', 'Despite that the weather was poor, the outdoor concert continued as scheduled.', '["Despite that the weather","was poor,","the outdoor concert continued","as scheduled"]', 0, '"despite"は前置詞であり、"that"節を直接続けることはできない。"Despite the fact that"とするか、単に"Although the weather was poor"とする必要がある。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e54', 'structure', NULL, 'structure_error_id', 'She is best qualified candidate for the position, based on her extensive experience.', '["She is best qualified","candidate for the position,","based on her","extensive experience"]', 0, '最上級の形容詞には定冠詞"the"が必要("the best qualified candidate")。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e55', 'structure', NULL, 'structure_error_id', 'She had her car repair by a mechanic the day before the road trip.', '["She had her car repair","by a mechanic","the day before","the road trip"]', 0, '使役構文"have something done"には過去分詞が必要で、原形の"repair"は使えない。正しくは"had her car repaired"。', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e56', 'structure', NULL, 'structure_error_id', 'The majority of the students has completed the assignment ahead of the deadline.', '["The majority of","the students has completed","the assignment","ahead of the deadline"]', 1, '"the majority of"の後に複数名詞("students")が続く場合は複数形の動詞を取るため、"has completed"ではなく"have completed"が正しい。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-1', 'reading', 'p-horse', 'reading_comprehension', 'What is the main purpose of the passage?', '["To argue that horses were never domesticated on the Eurasian steppe","To describe how genetic research has revised earlier ideas about where and when horses were domesticated","To explain the biological differences between wild and domestic horses","To criticize archaeologists for relying on indirect evidence"]', 1, '本文は、遺伝子研究によって馬の家畜化に関する定説が、以前のカザフスタン草原説からヴォルガ・ドン地域説へと移り変わった経緯をたどっています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-2', 'reading', 'p-horse', 'reading_comprehension', 'According to the passage, what evidence originally supported the theory that horses were domesticated in Kazakhstan?', '["Genetic comparisons of ancient horse DNA","Cave paintings depicting horseback riding","Wear patterns on horse teeth and large deposits of horse bones","Written records from early steppe civilizations"]', 2, '本文には、以前の説が "rested largely on indirect evidence: wear patterns on horse teeth... and unusually large deposits of horse bones"(間接的な証拠、すなわち馬の歯のすり減り方や大量の馬の骨の堆積に大きく依拠していた)とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-3', 'reading', 'p-horse', 'reading_comprehension', 'The word "prevailing" in the passage is closest in meaning to', '["outdated","dominant","controversial","incorrect"]', 1, '"prevailing" は当時最も広く受け入れられていた見解、つまり「支配的な」見解を表します。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-4', 'reading', 'p-horse', 'reading_comprehension', 'It can be inferred from the passage that the horses from the lower Volga-Don region spread quickly because', '["they were transported by boat across major rivers","they had traits that made them easier to control and ride","local horse populations had already died out","they were traded exclusively among steppe nomads"]', 1, '本文では、急速な広がりは "a calmer temperament and a stronger backbone"(穏やかな気性とより強靭な背骨)という特徴と結び付けられており、これらの特徴によって馬は制御しやすく、乗馬に適していました。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-5', 'reading', 'p-horse', 'reading_comprehension', 'The word "This population" in paragraph 2 refers to', '["modern domestic horses","researchers studying ancient DNA","the horses from the lower Volga-Don region","horses on the Kazakhstan steppe"]', 2, 'この語句は、直前にある "a single population that lived in the lower Volga-Don region"(ヴォルガ・ドン下流域に生息していた単一の集団)という記述を指しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-6', 'reading', 'p-horse', 'reading_comprehension', 'According to the passage, all of the following are mentioned as being affected by horse domestication EXCEPT', '["transportation","warfare","trade","agriculture"]', 3, '最終段落では輸送・戦争・交易が挙げられていますが、農業については本文中で触れられていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-1', 'reading', 'p-coral', 'reading_comprehension', 'What is the passage mainly about?', '["The variety of species that live in coral reefs","How rising water temperatures disrupt the relationship between coral and algae","Methods scientists use to measure ocean temperature","The life cycle of zooxanthellae algae"]', 1, '本文は、熱ストレスによってサンゴと藻類の共生関係が崩れ、白化現象が起こる仕組みを中心に述べています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-2', 'reading', 'p-coral', 'reading_comprehension', 'According to the passage, what do zooxanthellae algae provide to coral polyps?', '["Protection from predators","A hard calcium carbonate skeleton","Nutrients through photosynthesis","Compounds needed for reproduction"]', 2, '本文には藻類が "photosynthesize and supply the coral with nutrients"(光合成を行いサンゴに栄養を供給する)とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-3', 'reading', 'p-coral', 'reading_comprehension', 'The word "translucent" in the passage is closest in meaning to', '["brightly colored","partly transparent","extremely fragile","thickly layered"]', 1, '"translucent" は白い骨格が透けて見える組織を表す語で、つまり「半透明の」という意味です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-4', 'reading', 'p-coral', 'reading_comprehension', 'It can be inferred from the passage that a bleached coral reef would appear', '["darker than a healthy reef","the same color as a healthy reef","paler or whiter than a healthy reef","covered in algae"]', 2, '白化は色を与えている藻類が失われた後に白い骨格が露出する現象なので、白化したサンゴ礁はより白っぽく、色が薄く見えるはずです。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-5', 'reading', 'p-coral', 'reading_comprehension', 'The word "this partnership" in paragraph 2 refers to', '["the relationship between coral polyps and zooxanthellae algae","the relationship between scientists and reef ecosystems","the connection between ocean currents and temperature","the balance between predators and prey on the reef"]', 0, '第1段落でサンゴと藻類の共生関係が説明されており、第2段落の "this partnership" はそれを指しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-6', 'reading', 'p-coral', 'reading_comprehension', 'According to the passage, all of the following are true about coral recovery EXCEPT', '["bleached coral can sometimes recover if temperatures return to normal quickly","coral grows only a few centimeters per year","recovery from severe bleaching can take decades","coral recovers fully within a single year regardless of damage"]', 3, '本文には深刻な白化からの回復には "can take decades"(数十年かかることもある)とあり、1年以内に完全回復するという記述とは直接矛盾します。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-1', 'reading', 'p-impressionism', 'reading_comprehension', 'What is the main topic of the passage?', '["The biography of Claude Monet","The origin and development of Impressionist painting","The rules of the official Salon exhibition","A comparison between Impressionism and modern art"]', 1, '本文は、印象派が侮蔑的な呼び名として始まり、やがて確立された芸術運動へと発展していった経緯をたどっています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-2', 'reading', 'p-impressionism', 'reading_comprehension', 'According to the passage, how did the term "Impressionist" originate?', '["The artists chose it themselves before their first exhibition","A critic used it to mock a painting by Claude Monet","It was the name of the gallery where the artists exhibited","It referred to a technique taught at the official Salon"]', 1, '本文には、ある批評家が "mocking a Claude Monet painting... coined the term ''Impressionist'' as an insult"(クロード・モネの絵画をあざけって「印象派」という語を侮辱として作り出した)とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-3', 'reading', 'p-impressionism', 'reading_comprehension', 'The word "transient" in the passage is closest in meaning to', '["permanent","brief","colorful","natural"]', 1, '"transient effects of natural light" は、すぐに変化する光の効果、つまり「一時的な」効果を指しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-4', 'reading', 'p-impressionism', 'reading_comprehension', 'It can be inferred from the passage that the official Salon exhibition preferred paintings that were', '["painted quickly outdoors","based on everyday, modern subjects","carefully composed with smooth, blended surfaces","rejected by professional art dealers"]', 2, '本文では、印象派の目に見える筆致と、"the smooth, blended surfaces the Salon prized"(サロンが高く評価していた滑らかで混ぜ合わされた画面)とが対比されています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-5', 'reading', 'p-impressionism', 'reading_comprehension', 'The word "their" in paragraph 3 refers to', '["the critics''","the dealers''","the artists''","the Salon''s"]', 2, 'この文は画商たちが "the artists'' work"(画家たちの作品)を売り込んでいたことを述べているので、"their" は画家たちを指します。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-6', 'reading', 'p-impressionism', 'reading_comprehension', 'According to the passage, all of the following are mentioned as subjects favored by Impressionist painters EXCEPT', '["train stations","cafes","riverside gatherings","mythological scenes"]', 3, '本文では駅・カフェ・川辺の集いが好んで描かれた題材として挙げられている一方、神話の場面は印象派が離れていった題材として述べられています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-1', 'reading', 'p-insulin', 'reading_comprehension', 'What is the passage mainly about?', '["The symptoms of type 1 diabetes in children","How insulin was discovered and rapidly developed into a treatment","The history of the Nobel Prize in Physiology or Medicine","Surgical techniques used on laboratory animals in the 1920s"]', 1, '本文は、膵臓に関する初期の研究からインスリンが発見され、それが急速に命を救う治療法へと発展していった経緯をたどっています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-2', 'reading', 'p-insulin', 'reading_comprehension', 'According to the passage, why had earlier attempts to isolate the pancreatic substance failed?', '["Researchers could not identify which organ was involved","Digestive enzymes in the pancreas broke down the substance before it could be extracted","No diabetic patients were willing to participate in trials","The equipment needed for extraction had not yet been invented"]', 1, '本文には、以前の試みが失敗したのは "largely because digestive enzymes in the pancreas broke down the substance before it could be extracted in usable form"(膵臓内の消化酵素が、その物質を使える形で抽出する前に分解してしまっていたため)とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-3', 'reading', 'p-insulin', 'reading_comprehension', 'The word "degenerate" in the passage is closest in meaning to', '["multiply","break down","become active","relocate"]', 1, '"degenerate" は膵管を結紮した後に組織が劣化していく様子、つまり「分解する」ことを表しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-4', 'reading', 'p-insulin', 'reading_comprehension', 'It can be inferred from the passage that tying off the pancreatic duct was significant because it', '["increased the number of insulin-producing cells","allowed the enzyme-producing tissue to be destroyed while preserving insulin-producing cells","eliminated the need for laboratory animals","cured the dogs'' diabetes permanently"]', 1, '本文では、この方法によって酵素を産生する組織を分解させる一方で、"while preserving the cells now known to produce insulin"(現在インスリンを産生することが分かっている細胞は保存された)と説明されています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-5', 'reading', 'p-insulin', 'reading_comprehension', 'The word "it" in paragraph 2, in the phrase "to make it safe for humans," refers to', '["the pancreatic duct","the extraction process","the substance/extract","the laboratory"]', 2, 'コリップは抽出された物質を人間が安全に使えるように、抽出プロセスを改良しました。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-6', 'reading', 'p-insulin', 'reading_comprehension', 'According to the passage, all of the following people are mentioned as contributing to the discovery of insulin EXCEPT', '["Frederick Banting","Charles Best","James Collip","Alexander Fleming"]', 3, '本文にはバンティング、ベスト、コリップ(およびマクラウド)の名前が挙げられていますが、アレクサンダー・フレミングについては触れられていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-1', 'reading', 'p-urban-heat', 'reading_comprehension', 'What is the main purpose of the passage?', '["To explain the causes and effects of the urban heat island effect and how cities are addressing it","To compare temperatures in different cities around the world","To argue that urban development should be halted","To describe how air conditioning units work"]', 0, '本文は、ヒートアイランド現象の原因、その影響、そして都市が試みている対策について説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-2', 'reading', 'p-urban-heat', 'reading_comprehension', 'According to the passage, what is the primary cause of the urban heat island effect?', '["Waste heat from vehicles alone","Materials like asphalt and dark rooftops absorbing and releasing solar radiation","The height of buildings blocking sunlight","A lack of rainfall in cities"]', 1, '本文には、主な原因はアスファルトや濃い色の屋根材などが "absorb far more solar radiation... then slowly release that stored heat after sunset"(日中に太陽光をはるかに多く吸収し、日没後にその蓄えた熱をゆっくり放出する)ことだとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-3', 'reading', 'p-urban-heat', 'reading_comprehension', 'The word "compound" in the passage is closest in meaning to', '["reduce","explain","intensify","measure"]', 2, '"compound the effect" は他の要因がその効果をさらに強める、つまり「増強する」という意味です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-4', 'reading', 'p-urban-heat', 'reading_comprehension', 'It can be inferred from the passage that green roofs help mitigate the urban heat island effect because they', '["generate electricity for the building","reduce the amount of solar energy absorbed by rooftop surfaces","eliminate the need for tall buildings","increase waste heat from air conditioning"]', 1, '屋上緑化は、"reduce how much solar energy urban surfaces absorb and retain"(都市の表面が吸収・保持する太陽エネルギーの量を減らす)ことを目的とした対策の一つとして挙げられています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-5', 'reading', 'p-urban-heat', 'reading_comprehension', 'The word "it" in paragraph 1, in the phrase "release that stored heat," refers to heat stored in', '["rural vegetation","the atmosphere generally","urban construction materials such as asphalt and rooftops","air conditioning units"]', 2, 'ここで言う熱とは、日中に都市の建築資材が吸収した太陽放射のことです。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-6', 'reading', 'p-urban-heat', 'reading_comprehension', 'According to the passage, all of the following are mentioned as mitigation strategies EXCEPT', '["reflective roofing materials","expanded tree canopy coverage","green roofs","banning private vehicles"]', 3, '本文では反射性のある屋根材、樹冠(緑地)の拡大、屋上緑化が対策として挙げられていますが、車両の禁止については触れられていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-1', 'reading', 'p-silk-road', 'reading_comprehension', 'What is the main idea of the passage?', '["The Silk Road was primarily a route for trading silk between China and Europe","The Silk Road facilitated a broad exchange of goods, ideas, and technologies with lasting economic significance","The Silk Road declined because of religious conflict","Papermaking technology was invented along the Silk Road"]', 1, '本文は、シルクロードが絹以外にもはるかに多くのものを運び、経済的・文化的に長く続く遺産を残したことを強調しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-2', 'reading', 'p-silk-road', 'reading_comprehension', 'According to the passage, what caused the decline of the Silk Road network?', '["The invention of paper","The rise of direct sea trade between Europe and Asia","A decline in demand for silk","The spread of Buddhism"]', 1, '本文には、このネットワークは "following the rise of direct sea trade between Europe and Asia"(ヨーロッパとアジア間の直接海上貿易の台頭を受けて)衰退したとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-3', 'reading', 'p-silk-road', 'reading_comprehension', 'The word "disseminated" in the passage is closest in meaning to', '["destroyed","spread","translated","hidden"]', 1, '"disseminated" は、製紙技術が新しい地域に伝わった後に情報が記録され広まっていった様子を表しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-4', 'reading', 'p-silk-road', 'reading_comprehension', 'It can be inferred from the passage that cities like Samarkand and Kashgar prospered mainly because they', '["produced large quantities of silk","were located strategically along trade routes","had large populations of merchants who manufactured goods","banned foreign traders from entering"]', 1, '本文には、これらの都市が繁栄したのは "largely because of their strategic locations rather than their own manufacturing output"(自らの生産力よりも主に戦略的な立地のおかげ)だとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-5', 'reading', 'p-silk-road', 'reading_comprehension', 'The word "its" in paragraph 1, in the phrase "the network''s decline," refers to', '["China''s","the Mediterranean''s","the Silk Road''s","Europe''s"]', 2, 'この語句は、同じ文の前半で述べられているシルクロードのネットワークの衰退を指しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-6', 'reading', 'p-silk-road', 'reading_comprehension', 'According to the passage, all of the following are mentioned as having traveled along the Silk Road EXCEPT', '["spices","papermaking technology","Buddhism","firearms"]', 3, '本文では香辛料、製紙技術、仏教の伝播について触れられていますが、火器については言及されていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-1', 'reading', 'p-photosynthesis', 'reading_comprehension', 'What is the passage mainly about?', '["The chemical structure of RuBisCO","How C4 photosynthesis helps certain plants cope with hot, dry conditions more efficiently than C3 photosynthesis","The history of maize cultivation","Methods for irrigating crops in arid regions"]', 1, '本文はC4光合成の仕組みと、それが通常のC3光合成と比べてなぜ高温乾燥環境で有利になるのかを説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-2', 'reading', 'p-photosynthesis', 'reading_comprehension', 'According to the passage, what problem does photorespiration cause in C3 plants?', '["It prevents leaf pores from closing","It reduces the energy available for growth because RuBisCO binds oxygen instead of carbon dioxide","It causes plants to lose their leaves","It increases the rate of water loss through roots"]', 1, '本文に "a wasteful side reaction... that reduces the energy available for growth" とあるように、RuBisCOが二酸化炭素の代わりに酸素と結合すると光呼吸が起こり、成長に使えるエネルギーが減少します。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-3', 'reading', 'p-photosynthesis', 'reading_comprehension', 'The word "suppressing" in the passage is closest in meaning to', '["causing","measuring","preventing","accelerating"]', 2, '"Suppressing the conditions that lead to photorespiration" は、光呼吸につながる条件が起こらないようにする、という意味です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-4', 'reading', 'p-photosynthesis', 'reading_comprehension', 'It can be inferred from the passage that C4 plants have an advantage over C3 plants primarily in', '["cold, cloudy climates","hot, sunny, and relatively dry climates","climates with very high rainfall only","environments with no sunlight"]', 1, '本文はC4植物が "hot, sunny climates" でも光合成を維持しながら水分を節約できると説明しており、そのため高温で日差しの強い気候において有利になります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-5', 'reading', 'p-photosynthesis', 'reading_comprehension', 'The word "these plants" in paragraph 2 refers to', '["all plants that use C3 photosynthesis","maize, sugarcane, and sorghum","researchers studying photosynthesis","plants found only in tropical rainforests"]', 1, '第2段落の冒頭でトウモロコシ、サトウキビ、ソルガムがここで説明されているC4植物の例として挙げられています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-6', 'reading', 'p-photosynthesis', 'reading_comprehension', 'According to the passage, all of the following are mentioned as examples of C4 plants EXCEPT', '["maize","sugarcane","sorghum","wheat"]', 3, '本文はトウモロコシ、サトウキビ、ソルガムをC4植物として挙げていますが、小麦については触れていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-1', 'reading', 'p-bronze-age', 'reading_comprehension', 'What is the passage mainly about?', '["The daily life of Mycenaean Greek citizens","The likely causes and regional consequences of the Bronze Age Collapse","The invention of bronze metallurgy","A comparison between Egyptian and Hittite writing systems"]', 1, '本文は青銅器時代の崩壊の考えられる原因と、その影響が地域によってどう異なったかを論じています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-2', 'reading', 'p-bronze-age', 'reading_comprehension', 'According to the passage, what happened to writing systems in several regions after the collapse?', '["They were simplified but continued in use","They disappeared for centuries","They were replaced by a single universal script","They were used only by the Sea Peoples"]', 1, '本文には文字体系が "disappeared in several regions for centuries afterward" とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-3', 'reading', 'p-bronze-age', 'reading_comprehension', 'The word "overwhelm" in the passage is closest in meaning to', '["support","explain","exceed the capacity of","postpone"]', 2, '"Overwhelm these interconnected societies" は、複合的なストレスがこれらの社会の許容範囲を超えたことを意味します。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-4', 'reading', 'p-bronze-age', 'reading_comprehension', 'It can be inferred from the passage that trade in tin was significant because', '["tin was used as currency across the region","tin was needed to produce bronze, linking these societies economically","tin was the primary food source for coastal populations","tin mining caused the initial drought"]', 1, '本文は各社会が "grown economically interdependent through trade in tin and other resources needed to produce bronze" と説明しており、錫の交易が経済的な結びつきを生んでいたことがわかります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-5', 'reading', 'p-bronze-age', 'reading_comprehension', 'The word "these societies" in paragraph 2 refers to', '["modern historians","the civilizations affected by the Bronze Age Collapse","the Sea Peoples specifically","only the Egyptian civilization"]', 1, 'このフレーズは第1段落で説明されている、崩壊の影響を受けた文明を指しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-6', 'reading', 'p-bronze-age', 'reading_comprehension', 'According to the passage, all of the following are mentioned as factors or evidence related to the collapse EXCEPT', '["raids by the Sea Peoples","a period of prolonged drought","the disruption of trade networks","a major volcanic eruption"]', 3, '本文は「海の民」による襲撃、長期の干ばつ、貿易網の崩壊に触れていますが、大規模な火山噴火については述べていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-1', 'reading', 'p-loss-aversion', 'reading_comprehension', 'What is the passage mainly about?', '["The mathematical formula behind expected value","How loss aversion causes people to deviate from purely rational economic behavior","The biography of Daniel Kahneman","Why retailers offer limited-time discounts"]', 1, '本文は損失回避について説明し、それが合理的な経済モデルから外れた行動をどのように引き起こすかの例をいくつか挙げています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-2', 'reading', 'p-loss-aversion', 'reading_comprehension', 'According to the passage, what did Kahneman and Tversky find about how people experience losses and gains?', '["People feel gains and losses with equal intensity","People feel the pain of a loss about twice as intensely as an equivalent gain","People barely notice small financial losses","People prefer losses to gains in most situations"]', 1, '本文に "feel the pain of a loss roughly twice as intensely as the pleasure of an equivalent gain" とあるように、人は損失の痛みを同額の利益の喜びの約2倍強く感じるとされています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-3', 'reading', 'p-loss-aversion', 'reading_comprehension', 'The word "asymmetry" in the passage is closest in meaning to', '["balance","imbalance","similarity","calculation"]', 1, '損失と利益を感じる強さの違いは非対称性(asymmetry)、つまり不均衡として説明されています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-4', 'reading', 'p-loss-aversion', 'reading_comprehension', 'It can be inferred from the passage that an investor influenced by loss aversion would most likely', '["sell a losing stock immediately to avoid further risk","hold onto a declining stock longer than a rational strategy would suggest","refuse to invest in the stock market at all","treat gains and losses exactly the same way"]', 1, '本文には投資家が "often hold onto declining stocks far longer than a purely rational strategy would recommend" とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-5', 'reading', 'p-loss-aversion', 'reading_comprehension', 'The word "which" in paragraph 3, in the phrase "which tends to be more motivating," refers to', '["offering a limited-time discount framed as a potential gain","framing a limited-time discount as an opportunity to avoid losing out","the retirement savings program","the coin-flip bet described in paragraph 2"]', 1, 'この文は、損失を避ける機会として値引きを見せる方法(より動機づけになる)を、利益として見せる場合と対比しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-6', 'reading', 'p-loss-aversion', 'reading_comprehension', 'According to the passage, all of the following are mentioned as examples influenced by loss aversion EXCEPT', '["investors holding onto declining stocks","people rejecting a fair coin-flip bet","retailers framing discounts around avoiding loss","consumers preferring generic brands over name brands"]', 3, '本文は投資家の行動、コイントスの賭け、小売業者の値引きの見せ方を例として挙げていますが、ブランドの好みについては触れていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-1', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'What is the passage mainly about?', '["Alfred Wegener''s personal life","How the theory of continental drift evolved into the modern theory of plate tectonics","The formation of mountain ranges specifically","Methods used to predict earthquakes"]', 1, '本文はウェゲナーの当初の理論から海洋底拡大の発見を経て現代のプレートテクトニクス理論に至る流れをたどっています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-2', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'According to the passage, why did most geologists initially reject Wegener''s theory?', '["His evidence about coastlines was considered fabricated","He could not identify a plausible mechanism for continents moving through solid ocean floor","He refused to publish his findings","Fossil evidence contradicted his theory"]', 1, '本文には地質学者たちが理論を否定した理由として "largely because he could not identify a plausible mechanism" とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-3', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'The word "plausible" in the passage is closest in meaning to', '["impossible","believable","famous","ancient"]', 1, '"Plausible mechanism" とは、信頼できる、説得力のある仕組みという意味です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-4', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'It can be inferred from the passage that the discovery of seafloor spreading was important because it', '["proved that continents do not move at all","provided a mechanism that made continental drift scientifically credible","disproved the existence of mid-ocean ridges","showed that Pangaea never existed"]', 1, '本文には海洋底拡大が "provided the missing mechanism" とあり、ウェゲナーの理論に欠けていた仕組みを補ったことがわかります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-5', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'The word "This framework" in paragraph 3 refers to', '["Wegener''s original 1912 theory","the technology used to map the ocean floor","the modern theory of plate tectonics","the distribution of fossils across continents"]', 2, '"This framework" は、同じ段落の前半で説明されている現代のプレートテクトニクス理論を指しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-6', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'According to the passage, all of the following are mentioned as evidence or phenomena related to plate tectonics EXCEPT', '["matching coastlines of South America and Africa","mid-ocean ridges","the distribution of earthquakes and volcanoes","the discovery of a ninth continent"]', 3, '本文は一致する海岸線、海嶺(海洋底の中央海嶺)、地震・火山の分布について触れていますが、9番目の大陸の発見については述べていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-1', 'reading', 'p-printing-press', 'reading_comprehension', 'What is the passage mainly about?', '["The biography of Johannes Gutenberg","How the printing press transformed the production and spread of written knowledge in Europe","The history of papermaking in East Asia","The religious teachings of Martin Luther"]', 1, '本文はグーテンベルクの印刷システムと、それがヨーロッパにおける知識の広がりに与えた幅広い影響を説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-2', 'reading', 'p-printing-press', 'reading_comprehension', 'According to the passage, what technologies did Gutenberg combine in his printing system?', '["Woodblock carving and handwritten calligraphy","Movable metal type, oil-based ink, and a modified wine press","Paper made from wood pulp and a steam-powered press","Movable type invented by Martin Luther"]', 1, '本文には "combined movable metal type, an oil-based ink suited to metal surfaces, and a modified wine press" とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-3', 'reading', 'p-printing-press', 'reading_comprehension', 'The word "accelerate" in the passage is closest in meaning to', '["slow down","speed up","prevent","record"]', 1, '"Accelerate the spread of new scientific ideas" は、その広がりを加速させる、という意味です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-4', 'reading', 'p-printing-press', 'reading_comprehension', 'It can be inferred from the passage that before the printing press, access to books was', '["available equally to all social classes","limited mainly to monasteries, universities, and wealthy patrons","restricted entirely to religious texts","more widespread than after the printing press"]', 1, '本文には手書きの写本が "limited to a small number of copies held by monasteries, universities, and wealthy patrons" とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-5', 'reading', 'p-printing-press', 'reading_comprehension', 'The word "earlier reform movements" in paragraph 3 is used to contrast with', '["the speed at which Martin Luther could distribute his writings using the printing press","the invention of movable type in East Asia","the wine press used by Gutenberg","the rise in literacy rates"]', 0, '本文は、印刷術を持たなかった以前の改革者たちと比べて、ルターが印刷術を使っていかに速く自分の著作を広められたかを対比しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-6', 'reading', 'p-printing-press', 'reading_comprehension', 'According to the passage, all of the following are mentioned as effects of the printing press EXCEPT', '["a drop in the cost of producing books","faster spread of scientific ideas","rising literacy rates","the abolition of monasteries"]', 3, '本文は書籍のコスト低下、科学的思想の広がりの加速、識字率の上昇に触れていますが、修道院の廃止については述べていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-1', 'reading', 'p-octopus', 'reading_comprehension', 'What is the passage mainly about?', '["The diet of wild octopuses","The octopus''s unusual nervous system and its role in rapid camouflage","A comparison between octopuses and squid","How chromatophores are used in human medical research"]', 1, '本文はタコの分散型神経系と、それが素早い擬態をどう支えているかを説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-2', 'reading', 'p-octopus', 'reading_comprehension', 'According to the passage, where are roughly two-thirds of an octopus''s neurons located?', '["In the central brain","In the eyes","Distributed throughout its eight arms","In the skin''s chromatophores"]', 2, '本文には "roughly two-thirds of an octopus''s several hundred million neurons are distributed throughout its eight arms" とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-3', 'reading', 'p-octopus', 'reading_comprehension', 'The word "distributed" in the passage is closest in meaning to', '["concentrated","spread out","removed","duplicated"]', 1, '"Distributed throughout its eight arms" は、一箇所に集中せず8本の腕全体に広がっている、という意味です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-4', 'reading', 'p-octopus', 'reading_comprehension', 'It can be inferred from the passage that octopus camouflage is puzzling to researchers mainly because', '["octopuses cannot move their arms independently","octopuses appear to be colorblind yet can match colors in their environment","chromatophores are found only in a few octopus species","octopuses never change their skin texture"]', 1, '本文はタコが "are believed to be colorblind" にもかかわらず周囲の色に合わせられる点が謎だと述べています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-5', 'reading', 'p-octopus', 'reading_comprehension', 'The word "this ability" in paragraph 2 refers to', '["the octopus''s distributed nervous system","the octopus''s near-instantaneous camouflage","the octopus''s sense of touch","the octopus''s diet"]', 1, '"This ability" は、第2段落の冒頭で紹介された、瞬時に近い擬態能力を指しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-6', 'reading', 'p-octopus', 'reading_comprehension', 'According to the passage, all of the following are mentioned as being involved in octopus camouflage EXCEPT', '["chromatophores","papillae that reshape skin texture","light-sensitive proteins in the skin","color-sensitive cone cells in the eyes"]', 3, '本文はタコには色感受性の錐体細胞が欠けていると述べており、色素胞・乳頭・皮膚の光感受性タンパク質はいずれも擬態に関わるものとして挙げられています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-1', 'reading', 'p-dust-bowl', 'reading_comprehension', 'What is the passage mainly about?', '["The geography of the Great Plains","The causes and consequences of the Dust Bowl","The history of wheat prices in the United States","Federal tax policy during the 1930s"]', 1, '本文はダストボウルの自然的・人為的な原因と、それが農家や政策に与えた影響を説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-2', 'reading', 'p-dust-bowl', 'reading_comprehension', 'According to the passage, what practice contributed to the exposure of topsoil before the Dust Bowl?', '["Farmers planting deep-rooted prairie grasses","Farmers plowing under native prairie grasses to plant wheat","Farmers irrigating their fields excessively","Farmers abandoning their land entirely"]', 1, '本文には農家が "had plowed under vast areas of native prairie grasses to plant wheat" とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-3', 'reading', 'p-dust-bowl', 'reading_comprehension', 'The word "anchored" in the passage is closest in meaning to', '["loosened","secured","fertilized","flooded"]', 1, '"Anchored the soil" は、土壌をしっかりと固定していた、という意味です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-4', 'reading', 'p-dust-bowl', 'reading_comprehension', 'It can be inferred from the passage that the Dust Bowl would have been less severe if', '["wheat prices had risen even further","native prairie grasses had not been plowed under","the drought had lasted only a single year","more families had migrated to California"]', 1, '草原の草が土壌を固定し浸食を防いでいたため、それが耕されずに残っていればダストボウルの被害はより小さかったと考えられます。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-5', 'reading', 'p-dust-bowl', 'reading_comprehension', 'The word "them" in paragraph 2, in the phrase "without them," refers to', '["wheat farmers","deep-rooted prairie grasses","dust storms","federal conservation programs"]', 1, 'この文は、直前で述べられた深く根を張った草原の草が "without" だった場合に表土がどうなるかを説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-6', 'reading', 'p-dust-bowl', 'reading_comprehension', 'According to the passage, all of the following are mentioned as responses to or causes of the Dust Bowl EXCEPT', '["a multi-year drought beginning in 1931","plowing under native prairie grasses","contour plowing and windbreak trees promoted by the government","the construction of large-scale irrigation canals"]', 3, '本文は干ばつ、耕作の慣行、政府の土壌保全事業に触れていますが、大規模な灌漑用水路の建設については述べていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-1', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'What is the passage mainly about?', '["The biography of the Medici family","How the patronage system shaped the production and direction of Renaissance art","The techniques used to create the pigment ultramarine","A comparison between Renaissance and modern art markets"]', 1, '本文はパトロン制度がルネサンス美術の制作内容や、芸術家同士の競争のあり方をどう形作ったかを説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-2', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'According to the passage, what might a patron''s commission specify?', '["Only the general subject matter, with no other requirements","The artist''s political opinions","Exact dimensions, materials, and the number of figures to be included","The exact selling price of the finished work"]', 2, '本文には依頼内容が "exact dimensions, materials such as expensive pigments... and even the number of figures to be included" を指定しうるとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-3', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'The word "constrained" in the passage is closest in meaning to', '["expanded","limited","ignored","rewarded"]', 1, 'パトロンの好みが創作の選択を "constrained" したというのは、それらを制限したという意味です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-4', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'It can be inferred from the passage that Renaissance artists'' creative choices were often influenced by', '["government censorship laws","the specific preferences and demands of their patrons","the absence of any competition among artists","a complete lack of financial concerns"]', 1, '本文は芸術家が "had strong incentives to satisfy a patron''s specific tastes and demands" と説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-5', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'The word "This arrangement" in paragraph 2 refers to', '["the competition among artists for commissions","the patronage system described in paragraph 1","the technique of linear perspective","the political structure of Florence"]', 1, '"This arrangement" は、第1段落で紹介されたパトロン制度を指しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-6', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'According to the passage, all of the following are mentioned as motivations or effects related to patronage EXCEPT', '["displaying wealth and political influence","driving technical innovation through competition","satisfying a patron''s specific tastes","eliminating the need for skilled artists"]', 3, '本文は富や政治的影響力の誇示、競争による技術革新の促進、パトロンの好みを満たすことに触れていますが、熟練した芸術家の必要性をなくすことには触れておらず、むしろ本文の内容と矛盾します。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-1', 'reading', 'p-bird-navigation', 'reading_comprehension', 'What is the passage mainly about?', '["The reasons birds migrate in the first place","The multiple navigational systems migratory birds use to travel long distances","The specific migration routes of one bird species","How researchers tag birds for tracking studies"]', 1, '本文は渡り鳥が長距離を移動する際に用いる、地磁気感知・天体の位置・記憶地図など複数の重なり合うナビゲーションの仕組みを説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-2', 'reading', 'p-bird-navigation', 'reading_comprehension', 'According to the passage, what is magnetoreception?', '["The ability to see ultraviolet light","The ability to detect Earth''s magnetic field","The ability to smell familiar landscapes","The ability to remember visual landmarks"]', 1, '本文は磁気受容を "the ability to detect Earth''s magnetic field" と定義しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-3', 'reading', 'p-bird-navigation', 'reading_comprehension', 'The word "innate" in the passage is closest in meaning to', '["learned through practice","present from birth","extremely rare","impossible to study"]', 1, '"Innate rather than learned" な能力とは、生まれつき備わっている能力のことです。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-4', 'reading', 'p-bird-navigation', 'reading_comprehension', 'It can be inferred from the passage that young birds completing their first migration successfully suggests that', '["all navigational ability is learned from adult birds","at least some navigational ability is present without prior experience","young birds cannot navigate using magnetic fields","migration routes never change between generations"]', 1, '本文には若い鳥が "often complete the journey successfully even without prior experience or adult guidance" とあり、生まれつきの能力があることが示唆されています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-5', 'reading', 'p-bird-navigation', 'reading_comprehension', 'The word "this sense" in paragraph 2 refers to', '["the ability to see stars","the ability to detect Earth''s magnetic field","the ability to smell nesting sites","the ability to build mental maps"]', 1, '"This sense" は、その段落の前半で説明されている、地磁気を感知する磁気受容感覚を指しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-6', 'reading', 'p-bird-navigation', 'reading_comprehension', 'According to the passage, all of the following are mentioned as tools migratory birds may use to navigate EXCEPT', '["Earth''s magnetic field","the position of the sun and stars","visual landmarks and smell","radio signals from other birds"]', 3, '本文は地磁気、太陽や星の位置、目印や匂いに触れていますが、他の鳥からの電波信号については述べていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-1', 'reading', 'p-assembly-line', 'reading_comprehension', 'What is the passage mainly about?', '["The biography of Henry Ford","How the moving assembly line transformed manufacturing efficiency and had lasting effects on industry","The mechanical design of the Model T engine","Labor union strikes in the automobile industry"]', 1, '本文は組み立てライン(アセンブリーライン)が製造効率をどう変え、産業全体に長期的な影響を与えたかを説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-2', 'reading', 'p-assembly-line', 'reading_comprehension', 'According to the passage, how long did it take to build a car after the assembly line was introduced?', '["More than twelve hours","Roughly ninety minutes","Exactly one week","About thirty seconds"]', 1, '本文には工場が "reduced the time required to build a single car to roughly ninety minutes" とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-3', 'reading', 'p-assembly-line', 'reading_comprehension', 'The word "monotony" in the passage is closest in meaning to', '["danger","repetitiveness","complexity","high pay"]', 1, '"Monotony of repetitive tasks" は、単純作業の反復性を表しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-4', 'reading', 'p-assembly-line', 'reading_comprehension', 'It can be inferred from the passage that Ford increased assembly line workers'' wages partly because', '["government regulations required it","repetitive tasks caused high worker turnover that higher wages helped reduce","the Model T''s price was increasing rapidly","skilled craftsmanship became more valuable"]', 1, '本文には賃金上昇の理由として "in part to reduce the high turnover caused by the monotony of repetitive tasks" とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-5', 'reading', 'p-assembly-line', 'reading_comprehension', 'The word "it" in paragraph 3, in the phrase "it also drew criticism," refers to', '["the automobile industry generally","the assembly line","the Model T specifically","Henry Ford personally"]', 1, 'この文は、組み立てラインによる効率性の向上と、それが同時に受けた批判とを対比しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-6', 'reading', 'p-assembly-line', 'reading_comprehension', 'According to the passage, all of the following are mentioned as effects of the assembly line EXCEPT', '["a reduction in the time needed to build a car","lower prices for the Model T","criticism for reducing skilled work to repetitive tasks","the complete elimination of factory jobs"]', 3, '本文は建造時間の短縮、価格低下、単純労働化への批判に触れていますが、工場労働の完全な消滅については述べていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-1', 'reading', 'p-permafrost', 'reading_comprehension', 'What is the passage mainly about?', '["The engineering challenges of building roads in the Arctic","How permafrost thaw releases greenhouse gases and creates a warming feedback loop","The history of climate change research in Siberia","The difference between carbon dioxide and methane"]', 1, '本文は、永久凍土の融解が二酸化炭素とメタンを放出し、温暖化を加速させるフィードバックループを生み出す仕組みを説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-2', 'reading', 'p-permafrost', 'reading_comprehension', 'According to the passage, why did organic material in permafrost not fully decompose?', '["It was buried too deep underground","Cold temperatures prevented the microorganisms responsible for decay from functioning","It lacked the nutrients needed for microbial activity","It was chemically preserved by high salt content"]', 1, '本文には、低温によって分解を担う微生物の働きが妨げられていたため、有機物の分解が止まっていたとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-3', 'reading', 'p-permafrost', 'reading_comprehension', 'The word "dormant" in the passage is closest in meaning to', '["inactive","toxic","abundant","fragile"]', 0, '「Long-dormant organic material」は、長期間活動を停止した(=分解が進んでいない)物質を表しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-4', 'reading', 'p-permafrost', 'reading_comprehension', 'It can be inferred from the passage that permafrost thaw was not fully accounted for in earlier climate projections because', '["scientists did not believe the Arctic was warming","the carbon it released had previously been locked away and inaccessible","methane does not affect global temperatures","permafrost only exists in uninhabited regions"]', 1, '本文には、新たに放出されるこの炭素は「以前は閉じ込められており、過去の気候予測には織り込まれていなかった("was previously locked away and not accounted for in earlier climate projections")」とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-5', 'reading', 'p-permafrost', 'reading_comprehension', 'The word "it" in paragraph 3, in the phrase "as it thaws," refers to', '["the atmosphere","the infrastructure","the permafrost/ground","the pipeline"]', 2, 'この文は、インフラの下にある地面(永久凍土)が融解し、不均一に沈下していく様子を説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-6', 'reading', 'p-permafrost', 'reading_comprehension', 'According to the passage, all of the following are mentioned as being affected by permafrost thaw EXCEPT', '["buildings","roads","pipelines","ocean currents"]', 3, '本文では融解の影響を受けるものとして建物・道路・パイプラインが挙げられていますが、海流については言及がありません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-1', 'reading', 'p-hammurabi', 'reading_comprehension', 'What is the passage mainly about?', '["The military conquests of Hammurabi","The content, structure, and rediscovery of Hammurabi''s code of laws","The archaeology of ancient Iran","The daily life of Babylonian laborers"]', 1, '本文は、ハンムラビ法典の内容と構成、そして1901年の再発見の経緯を説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-2', 'reading', 'p-hammurabi', 'reading_comprehension', 'According to the passage, how many individual laws does Hammurabi''s code contain?', '["6","100","282","1754"]', 2, '本文に「法典は282の個別の法から成る("consists of 282 individual laws")」とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-3', 'reading', 'p-hammurabi', 'reading_comprehension', 'The word "proportional" in the passage is closest in meaning to', '["random","corresponding in degree","religious","unlimited"]', 1, '「Proportional retaliation」(比例的な報復)とは、「目には目を("an eye for an eye")」のように罪の重さに見合った罰を意味します。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-4', 'reading', 'p-hammurabi', 'reading_comprehension', 'It can be inferred from the passage that punishments under Hammurabi''s code were', '["identical regardless of social status","influenced by the social status of those involved","determined entirely by a jury","rarely enforced"]', 1, '本文には、実際に科される罰は「加害者と被害者双方の社会的地位に大きく左右されることが多かった("often depended heavily on the social status of both the offender and the victim")」とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-5', 'reading', 'p-hammurabi', 'reading_comprehension', 'The word "Its" in paragraph 3, in the phrase "Its rediscovery," refers to', '["Babylon''s","Iran''s","the stele''s","France''s"]', 2, 'この文は、ハンムラビ法典が刻まれた石碑(stele)が再発見されたことについて述べています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-6', 'reading', 'p-hammurabi', 'reading_comprehension', 'According to the passage, all of the following topics are mentioned as being addressed by the code EXCEPT', '["property disputes","fixed wages for laborers","liability for construction defects","rules for religious worship"]', 3, '本文では財産をめぐる紛争・労働者の賃金・欠陥工事の責任などが挙げられていますが、宗教儀礼に関する規定については言及がありません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-1', 'reading', 'p-lichen', 'reading_comprehension', 'What is the passage mainly about?', '["The classification of fungi","The symbiotic relationship between fungi and photosynthetic partners that forms lichen","The chemical composition of gravestones","How lichens are used in cooking"]', 1, '本文は、菌類と光合成を行うパートナーがどのように結びついて地衣類という複合生物を形成するかを説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-2', 'reading', 'p-lichen', 'reading_comprehension', 'According to the passage, what does the photosynthetic partner supply to the fungus?', '["Physical structure","Protection from sunlight","Carbohydrates produced through photosynthesis","Moisture retention"]', 2, '本文には、光合成を行うパートナーが「菌類が自ら作り出せない炭水化物を供給する("supplies the fungus with the carbohydrates it cannot manufacture on its own")」とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-3', 'reading', 'p-lichen', 'reading_comprehension', 'The word "desiccation" in the passage is closest in meaning to', '["drying out","overheating","freezing","decay"]', 0, '菌類は光合成パートナーを強い日光や乾燥(desiccation、つまり水分が失われて乾ききってしまうこと)から守っています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-4', 'reading', 'p-lichen', 'reading_comprehension', 'It can be inferred from the passage that fungi cannot survive alone in the way lichen does because they', '["cannot retain moisture","lack chlorophyll and cannot photosynthesize their own food","are too small to be seen without a microscope","require animal hosts to reproduce"]', 1, '本文には、菌類は「クロロフィルを持たない("lack chlorophyll")」ため、炭水化物の供給を光合成パートナーに頼っているとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-5', 'reading', 'p-lichen', 'reading_comprehension', 'The word "their" in paragraph 3, in the phrase "Their sensitivity to airborne pollutants," refers to', '["rocks","lichens","scientists","plants"]', 1, 'この段落は、地衣類が大気汚染物質に敏感であることが、大気質の指標として利用される理由になっていると説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-6', 'reading', 'p-lichen', 'reading_comprehension', 'According to the passage, all of the following are mentioned as environments where lichen grow EXCEPT', '["tropical rainforests","bare Arctic rock","tree bark","ocean floors"]', 3, '本文では熱帯雨林・北極の裸岩・樹皮が地衣類の生育環境として挙げられていますが、海底については言及がありません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-1', 'reading', 'p-vaccination', 'reading_comprehension', 'What is the passage mainly about?', '["The symptoms and history of smallpox outbreaks","How Edward Jenner developed and popularized vaccination against smallpox","The dangers of variolation as a medical practice","The global eradication of infectious diseases in general"]', 1, '本文は、ジェンナーの実験、「種痘(vaccination)」という用語の誕生、そしてその後の世界的な普及という流れを追っています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-2', 'reading', 'p-vaccination', 'reading_comprehension', 'According to the passage, what did rural folklore claim about milkmaids?', '["They were immune to all diseases","They rarely contracted smallpox after having cowpox","They discovered variolation","They refused all medical treatment"]', 1, '本文には、民間伝承では牛痘にかかったことのある乳搾りの女性たちは「天然痘にほとんどかからなかった("rarely contracted smallpox at all")」と信じられていたとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-3', 'reading', 'p-vaccination', 'reading_comprehension', 'The word "induce" in the passage is closest in meaning to', '["prevent","cause","diagnose","cure"]', 1, '人痘接種法(variolation)は、軽い症状を誘発する(induce、つまり引き起こす)ことを狙ったものでした。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-4', 'reading', 'p-vaccination', 'reading_comprehension', 'It can be inferred from the passage that variolation was considered riskier than Jenner''s method because it', '["used material from cowpox rather than smallpox","exposed people to actual smallpox material, which could cause fatal infection","was performed only on children","required no medical training"]', 1, '本文には、人痘接種法は天然痘の膿を用いており、「時に致命的な感染を引き起こすことがあった("sometimes caused fatal infections")」とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-5', 'reading', 'p-vaccination', 'reading_comprehension', 'The word "this" in paragraph 2, in the phrase "coined the term ''vaccination'' for this procedure," refers to', '["folk belief","variolation","the cowpox inoculation method Jenner tested","smallpox eradication"]', 2, '「This procedure」は、ジェンナーが少年に対して行ったばかりの、牛痘を用いた接種法を指します。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-6', 'reading', 'p-vaccination', 'reading_comprehension', 'According to the passage, all of the following are mentioned in connection with smallpox or its prevention EXCEPT', '["variolation","cowpox","Edward Jenner","antibiotics"]', 3, '本文では人痘接種法・牛痘・ジェンナーについて述べられていますが、ウイルス性の病気には効かない抗生物質については触れられていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-1', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'What is the passage mainly about?', '["The invention of steam power","How rapid industrial urbanization led to poor living conditions and eventual public health reform","The history of Manchester''s textile industry","The causes of cholera as a disease"]', 1, '本文は、産業革命期の急激な都市化が劣悪な生活環境を生み、やがて公衆衛生改革へとつながっていった経緯を追っています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-2', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'According to the passage, how did Manchester''s population change between 1770 and the following decades?', '["It stayed roughly the same","It grew from about twenty-five thousand to several hundred thousand","It declined sharply","It doubled and then declined"]', 1, '本文には、マンチェスターは「1770年には人口約2万5千人の小さな市場町だったが、数十年のうちに数十万人規模の都市へと成長した("grew from a modest market town of about twenty-five thousand people in 1770 to a city of several hundred thousand")」とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-3', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'The word "outpaced" in the passage is closest in meaning to', '["exceeded the speed of","financed","prevented","matched exactly"]', 0, '成長が行政のサービス提供能力を「outpaced(上回った)」というのは、行政の対応が追いつく速さを成長が超えてしまったという意味です。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-4', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'It can be inferred from the passage that cholera spread easily in industrial cities because', '["factories released toxic fumes into the air","many households shared contaminated water sources and sanitation facilities","workers refused to seek medical treatment","the cities were too sparsely populated"]', 1, '本文には、多くの世帯が一つの水源やトイレを共有しており、それが疾病の蔓延にとって理想的な状況を生み出したとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-5', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'The word "these" in paragraph 3, in the phrase "the severity of these outbreaks," refers to', '["factory closures","housing shortages","cholera outbreaks","political elections"]', 2, '直前の段落では、コレラの流行が工業都市に何度も広がっていった様子が説明されています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-6', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'According to the passage, all of the following are mentioned as results of industrial urbanization EXCEPT', '["overcrowded tenements","shared water sources and latrines","cholera outbreaks","declining factory employment"]', 3, '本文では過密な集合住宅・共有の水源やトイレ・コレラの流行が挙げられていますが、工場労働者の減少については言及がありません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-1', 'reading', 'p-echolocation', 'reading_comprehension', 'What is the passage mainly about?', '["The diet of insect-eating bats","How bats use echolocation to navigate and hunt, and the adaptations that make it possible","The evolution of bat wings","How sonar technology was invented"]', 1, '本文は、エコーロケーション(反響定位)の仕組みと、それを可能にする身体的な適応について説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-2', 'reading', 'p-echolocation', 'reading_comprehension', 'According to the passage, what information can a bat determine from returning echoes?', '["Only the distance of an object","The distance, direction, size, shape, texture, and movement of an object","The exact species of its prey","The temperature of the surrounding air"]', 1, '本文には、コウモリは「距離と方向...大きさ、形、質感、さらには動いているかどうかまで("distance and direction... size, shape, texture, and even whether it is moving")」判別できるとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-3', 'reading', 'p-echolocation', 'reading_comprehension', 'The word "faint" in the passage is closest in meaning to', '["loud","weak or hard to detect","delayed","artificial"]', 1, '「Faint returning echoes」とは、コウモリ自身の鳴き声に比べて弱く、感知しにくい反響音を指します。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-4', 'reading', 'p-echolocation', 'reading_comprehension', 'It can be inferred from the passage that without the middle-ear disconnection mechanism, bats would', '["be unable to fly","risk deafening themselves with their own calls","be unable to produce any sound","lose their sense of smell"]', 1, '本文は、この仕組みがコウモリを「自分自身の鳴き声によって耳が聞こえなくなること("from being deafened by its own call")」から守っていると説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-5', 'reading', 'p-echolocation', 'reading_comprehension', 'The word "its" in paragraph 3, in the phrase "drawn on its underlying principles," refers to', '["sonar","echolocation","radar","darkness"]', 1, '技術者たちは、ソナーやレーダーを開発する際にエコーロケーションの基本原理を応用しました。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-6', 'reading', 'p-echolocation', 'reading_comprehension', 'According to the passage, all of the following are mentioned in connection with bat echolocation EXCEPT', '["specialized laryngeal muscles","large, mobile outer ears","a middle-ear disconnection mechanism","infrared vision"]', 3, '本文では喉頭の筋肉・耳の形・中耳の仕組みについて述べられていますが、赤外線視覚については触れられていません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-1', 'reading', 'p-panama-canal', 'reading_comprehension', 'What is the passage mainly about?', '["The geography of the Isthmus of Panama","The failed French attempt and successful American completion of the Panama Canal","The biography of Ferdinand de Lesseps","The construction of the Suez Canal"]', 1, '本文は、失敗に終わったフランスによる試みと、それに続くアメリカによるパナマ運河の完成とを対比しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-2', 'reading', 'p-panama-canal', 'reading_comprehension', 'According to the passage, why did the French project ultimately fail?', '["A lack of interest from investors","Financial mismanagement, difficult terrain, and disease","Opposition from the Panamanian government","A shortage of construction materials"]', 1, '本文には、このプロジェクトは「財政の失敗、不安定な山岳地形、そして...病気が重なって("defeated by a combination of financial mismanagement, unstable mountainous terrain, and... disease")」失敗したとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-3', 'reading', 'p-panama-canal', 'reading_comprehension', 'The word "devastatingly" in the passage is closest in meaning to', '["surprisingly","mildly","destructively","slowly"]', 2, '病気は、フランスのプロジェクトを失敗させた原因の中でも最も「devastating(壊滅的)」、つまり最も破壊的なものとして描かれています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-4', 'reading', 'p-panama-canal', 'reading_comprehension', 'It can be inferred from the passage that the French were unable to control yellow fever and malaria mainly because', '["they had no doctors on site","the link between mosquitoes and disease transmission was not yet known","mosquitoes did not exist in Panama in the 1880s","yellow fever had not yet been identified as a disease"]', 1, '本文には、フランスの試みの当時は蚊と病気の関係が「まだ理解されていなかった("was not yet understood")」とあり、これが流行を制御できなかった理由を説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-5', 'reading', 'p-panama-canal', 'reading_comprehension', 'The word "This approach" in paragraph 2 refers to', '["the sea-level canal design","the lock-based system","the Suez Canal method","Gorgas''s mosquito control campaign"]', 1, 'この文は、ガトゥン湖を利用した閘門(こうもん)方式の説明の直後に続くものです。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-6', 'reading', 'p-panama-canal', 'reading_comprehension', 'According to the passage, all of the following are mentioned as factors in the canal''s completion EXCEPT', '["the lock-based system","Gatun Lake","mosquito control efforts","the invention of dynamite"]', 3, '本文では閘門方式・ガトゥン湖・ゴーガス医師による蚊の駆除活動について述べられていますが、ダイナマイトの発明については言及がありません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-1', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'What is the passage mainly about?', '["The biography of Leon Festinger","Cognitive dissonance theory and how people resolve contradictory beliefs","A specific religious group''s beliefs about the end of the world","Modern marketing techniques"]', 1, '本文は、認知的不協和理論と、人々が矛盾する信念をどのように解消するかについて説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-2', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'According to the passage, how did some group members react when the predicted end of the world did not occur?', '["They abandoned their belief immediately","They reinterpreted the failed prediction as evidence their faith had saved the world","They demanded a refund from the group''s leader","They stopped discussing the prediction entirely"]', 1, '本文には、メンバーたちは「失敗した予言を、自分たちの信仰が世界を救った証拠だと再解釈した("reinterpreted the failed prophecy as evidence that their faith had saved the world")」とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-3', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'The word "motivating" in the passage is closest in meaning to', '["confusing","driving someone to act","irrelevant","forgettable"]', 1, 'フェスティンガーは、不協和は「積極的に人を動かすもの("actively motivating")」であり、人々を矛盾の解消へと駆り立てると論じました。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-4', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'It can be inferred from the passage that cognitive dissonance theory can help explain why people', '["always change their beliefs when faced with contradictory evidence","sometimes continue investing in a failing project rather than admit a past mistake","never make decisions under uncertainty","prefer to work in groups rather than alone"]', 1, '本文には、この理論は、過去の投資が誤りだったと認めることを避けるために、失敗しつつあるプロジェクトへの投資を続けてしまう理由を説明できるとあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-5', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'The word "It" in paragraph 3, in the phrase "It helps explain why people often rate a decision more favorably," refers to', '["the failed prophecy","cognitive dissonance theory","the small group","Leon Festinger"]', 1, 'この段落は、認知的不協和理論が幅広く応用されてきたと述べたうえで、「It」はその理論を指し続けています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-6', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'According to the passage, all of the following are mentioned as strategies for resolving cognitive dissonance EXCEPT', '["adding new justifying beliefs","changing one''s behavior to match a belief","minimizing the perceived importance of the inconsistency","seeking therapy from a psychologist"]', 3, '本文では、正当化する新たな信念を加えること・信念に合わせて行動を変えること・矛盾の重要性を軽視することが挙げられていますが、心理療法を受けることへの言及はありません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-1', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'What is the passage mainly about?', '["The causes of low rainfall in desert regions","How desert plants and animals have adapted to water scarcity and temperature extremes","The life cycle of the cactus","The behavior of nocturnal predators"]', 1, '本文は、砂漠の植物や動物が水不足と極端な気温差にどのように適応してきたかを概観しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-2', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'According to the passage, how do many desert plants reduce water loss through their leaves?', '["By growing extremely large leaves","By having small, needle-like leaves or spines instead of broad leaves","By shedding all their leaves permanently","By growing only underground"]', 1, '本文には、多くの砂漠の植物は水を失いやすい広い葉の代わりに「小さく針のような葉やとげを持つ("small, needle-like leaves or spines")」とあります。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-3', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'The word "transpiration" in the passage is closest in meaning to', '["photosynthesis","the loss of water vapor from plant surfaces","the absorption of sunlight","root growth"]', 1, '広い葉は「transpiration(蒸散)」、つまり植物の表面から水蒸気が失われる現象によって急速に水分を失います。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-4', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'It can be inferred from the passage that opening pores only at night helps desert plants because', '["sunlight is not needed for photosynthesis at all","nighttime temperatures are lower, reducing water lost through the open pores","nocturnal animals pollinate the plants","carbon dioxide is more abundant at night"]', 1, '本文は、気孔が夜間に開くのは「気温が低く、失われる水分が少ないから("when temperatures are lower and less water is lost")」だと説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-5', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'The word "they" in paragraph 3, in the phrase "they can survive largely on water produced internally," refers to', '["desert plants","nocturnal predators","kangaroo rats (or similarly adapted species)","underground burrows"]', 2, 'この文は、カンガルーネズミが乾燥した種子を消化する過程で体内に作られる水分だけで、ほぼ生きていけることを説明しています。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-6', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'According to the passage, all of the following are mentioned as desert animal or plant adaptations EXCEPT', '["nocturnal behavior","water storage in thickened stems","highly efficient kidneys","migration to wetter climates during droughts"]', 3, '本文では夜行性の行動・多肉植物による貯水・効率的な腎臓が挙げられていますが、移動(migration)については言及がありません。', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
